const PACKAGE={"id":"BFSdual_LF06_Lernpfad_LS6_1","ls":"6.1","title":"Lernpfadübung · LS 6.1 · Die Nachfrage an zwei Standorten vergleichen","version":"1.1","source":"Fachbereiche/BFSdual/LF06/LS_6_1_Standorte_vergleichen.md"};
const COMP=[["Fachkompetenz","Ich vergleiche zwei Läden. Ich schaue auf Nachfrage, Verkaufsform und Fläche. Aus den Unterschieden leite ich Anforderungen an das Sortiment und die Warenpräsentation ab. Ich begründe diese Anforderungen für jeden Laden. Ich erkenne, welche Vorgaben der Laden unbedingt erfüllen muss."],["Personalkompetenz","Ich prüfe meine erste Idee mit Belegen."],["Sozialkompetenz","Ich höre die Ideen der anderen an. Ich begründe im Team, was für mich am wichtigsten ist."],["Methodenkompetenz","Ich ordne die Angaben zu beiden Läden nach denselben Kriterien."],["Medienkompetenz","Ich finde in einer Tabelle, Sprachnachricht oder Skizze die Angaben für meine Entscheidung."]];
const BANK=[{"c":0,"title":"Nachfrage bei Block","scene":"Block in Aurich erfasst 20 Kundenanfragen. Neun betreffen Sichtbarkeit auf dem Arbeitsweg, sechs das sichere Abstellen und fünf den Transport kleiner Dinge.","ask":"Welche Aussagen kannst du aus den Zahlen ableiten?","answer":[1,4],"options":["Das sichere Abstellen wurde am häufigsten genannt.","Sichtbarkeit auf dem Arbeitsweg ist das häufigste Hauptanliegen.","Bei 20 Anfragen wurden 20 Artikel verkauft.","Die Nachfrage nach Transport überwiegt die Nachfrage nach Sichtbarkeit.","Auch das sichere Abstellen ist ein belegter Kundenwunsch.","Genau neun Kundinnen und Kunden haben ein Lichtset gekauft."],"why":"Neun ist der höchste Wert. Auch die sechs Anfragen zum sicheren Abstellen belegen einen Bedarf. Die Angaben zählen Anfragen, keine Käufe.","hint":"Achte darauf, was gezählt wurde.","steps":"Vergleiche erst die drei Zahlen. Prüfe dann, ob die Antwort über Anfragen oder über Verkäufe spricht.","example":"Wenn acht Personen nach einem Produkt fragen, kann der Laden daraus noch keine acht Verkäufe ableiten.","sourceRefs":["M1"],"id":0,"l":1,"type":"multi","caseLabel":"LS 6.1 · Die Nachfrage an zwei Standorten vergleichen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"c":0,"title":"Nachfrage in der Bike Arena","scene":"Die Bike Arena Oltmanns in Leer erfasst 20 Anfragen. Acht betreffen Familienausflüge, sieben Reparaturen unterwegs, fünf besseren Regenschutz.","ask":"Welche Aussagen passen zum Profil der Kundschaft?","answer":[0,3,5],"options":["Familienausflüge wurden häufiger genannt als besserer Regenschutz.","Regenschutz wurde für die Aktion gar nicht nachgefragt.","Reparaturen unterwegs sind das Hauptanliegen von genau der Hälfte der Anfragen.","Die sieben Anfragen zu Reparaturen liefern einen weiteren Ansatz für die Auswahl.","Die meisten Anfragen betreffen ausschließlich Regenschutz.","Auch Regenschutz kam vor, selbst wenn er seltener genannt wurde."],"why":"Familienausflüge liegen mit acht vor Reparaturen mit sieben und Regenschutz mit fünf. Alle drei Themen wurden angesprochen.","hint":"Ordne die drei Anliegen nach der Zahl ihrer Nennungen.","steps":"Beurteile jede Aussage einzeln. Fünf von 20 sind ein Viertel, zehn wären die Hälfte.","example":"Eine seltenere Anfrage kann für einen Teil der Zielgruppe wichtig sein.","sourceRefs":["M2"],"id":1,"l":1,"type":"multi","caseLabel":"LS 6.1 · Die Nachfrage an zwei Standorten vergleichen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"c":0,"title":"Verkaufsformen vergleichen","scene":"Bei Block berät eine Fachkraft persönlich. In der Bike Arena wählt die Kundschaft auf der Aktionsfläche selbst; die Information ist bei Fragen ansprechbar.","ask":"Welche Merkmale der Verkaufsformen stimmen?","answer":[0,3],"options":["Bei Block ist eine Beratung am mitgebrachten Fahrrad möglich.","Selbstbedienung bedeutet, dass Fragen grundsätzlich unerwünscht sind.","In beiden Läden führt eine Fachkraft jede Person durch die Auswahl.","Auf der Aktionsfläche in Leer sollen Kundinnen und Kunden Waren selbst finden.","Der Satz ‚Die Aktion findet am Samstag statt‘ beschreibt die Verkaufsform.","Persönliche Beratung bedeutet, dass kein Schild verwendet werden darf."],"why":"Block kann Zubehör direkt am Fahrrad zeigen. In Leer soll die Auswahl zunächst selbstständig gelingen; für Rückfragen gibt es die Information.","hint":"Wer hilft bei der Auswahl? Wer sucht selbst aus?","steps":"Trenne Verkaufsform von Zeitpunkt, Fläche und Beschriftung.","example":"Trotz Selbstbedienung kann es eine Information geben, ohne dass jemand dauerhaft am Regal steht.","sourceRefs":["M1","M2"],"id":2,"l":1,"type":"multi","caseLabel":"LS 6.1 · Die Nachfrage an zwei Standorten vergleichen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"c":3,"title":"Anfragen richtig einordnen","scene":"Im Ladenprofil wurde für jede Anfrage genau ein Hauptanliegen notiert. Eine Person fragt nach einem Schloss, weil sie ihr Rad am Bahnhof anschließen will.","ask":"Welche Einträge passen zu dieser Auswertung?","answer":[2,5],"options":["Diese Anfragedaten beweisen, wie oft Fahrräder am Bahnhof gestohlen werden.","Die Frage wird unabhängig vom Zweck beim Thema ‚Verkaufsfläche‘ erfasst.","Der konkrete Wunsch kann ein Nachfragebeleg sein.","Die Anfrage zählt zugleich in jeder denkbaren Zubehörgruppe.","Der sichere Abstellplatz ist hier das gemessene Hauptanliegen des ganzen Ladens.","Als Hauptanliegen passt ‚Fahrrad sicher abstellen‘."],"why":"Die Kundenfrage belegt einen Bedarf. Für die Auswertung erhält sie im Fall genau ein Hauptanliegen: das sichere Abstellen.","hint":"Achte auf den Zweck des Schlosses in dieser Anfrage.","steps":"Unterscheide eine einzelne Anfrage von der häufigsten Kategorie im gesamten Laden.","example":"Wenn jemand eine Tasche für den Schlüssel sucht, ordnest du die Anfrage dem Transport kleiner Dinge zu.","sourceRefs":["M1","M6"],"id":3,"l":1,"type":"multi","caseLabel":"LS 6.1 · Die Nachfrage an zwei Standorten vergleichen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"c":0,"title":"Platz und Warenträger","scene":"Block hat 3,60 m × 3,20 m Aktionsfläche mit festem Tresen. Für Leer sind 6,40 m × 3,50 m und zwei Gondeln vorgesehen.","ask":"Welche Aussagen helfen dir, den Aufbau richtig zu planen?","answer":[0,1,2,5],"options":["Bei der Planung für Block muss der Tresen an seiner festen Position berücksichtigt werden.","Gondeln sind freistehende Regale, die hier von beiden Seiten erreichbar sein sollen.","Der Tresen beansprucht einen Teil der Aktionsfläche bei Block.","Die beiden Gondeln gehören zur geplanten Ausstattung von Block.","Die genannten Aktionsmaße stehen für die gesamte Ladenfläche.","Die beiden Aktionsflächen bieten unterschiedlich viel Platz."],"why":"Block hat weniger Fläche und einen festen Tresen. Die Gondeln in Leer sind für Ware auf zwei gegenüberliegenden Seiten vorgesehen.","hint":"Ordne jedes Maß und jeden Warenträger seinem Standort zu.","steps":"Frage dich: Ist der Warenträger fest, rollbar oder von mehreren Seiten nutzbar?","example":"Ein Wandregal kann von vorn erreichbar sein; eine beidseitig belegte Gondel braucht Zugang auf beiden Warenseiten.","sourceRefs":["M3","M6"],"id":4,"l":1,"type":"multi","caseLabel":"LS 6.1 · Die Nachfrage an zwei Standorten vergleichen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"c":3,"title":"Skizze lesen","scene":"Für eure Skizzen gilt der Maßstab 1:25. Der Hauptdurchgang bei Block ist in Wirklichkeit 1,20 m breit.","ask":"Welche Angaben sind richtig?","answer":[0,4],"options":["Ein Zentimeter im Plan entspricht 25 Zentimetern im Laden.","Der Hauptdurchgang muss im Plan 3,0 cm breit sein.","Der Durchgang wird im Plan 48 cm breit.","Der Maßstab bedeutet, dass je Laden 25 Artikel eingeplant werden.","Der Hauptdurchgang ist in der Skizze 4,8 cm breit.","Im Maßstab 1:25 darf jeder Laden die Wege nach Gefühl einzeichnen."],"why":"1,20 m sind 120 cm. 120 ÷ 25 = 4,8 cm im Plan. Der Maßstab verkleinert Längen im selben Verhältnis.","hint":"Rechne zuerst in Zentimeter um.","steps":"Teile die tatsächliche Breite durch 25 und gib das Ergebnis in Zentimetern an.","example":"50 cm im Laden werden bei 1:25 zu 2 cm im Plan.","sourceRefs":["M3"],"id":5,"l":1,"type":"multi","caseLabel":"LS 6.1 · Die Nachfrage an zwei Standorten vergleichen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"c":1,"title":"Die eigene Priorität prüfen","scene":"Du willst für Block ein zusätzliches Schild im Bereich des Werkstattzugangs aufstellen. Dann liest du, dass der Zugang frei bleiben muss. Die Ware kann auch am Regal klar beschriftet werden.","ask":"Welche Reaktion prüft deine erste Idee mit den Angaben zur Fläche?","answer":[3],"options":["Ich bleibe beim Schild am Zugang, weil ich es zuerst gewählt habe.","Ich nenne den Werkstattzugang und das Schild gleich wichtig und lasse die Entscheidung offen.","Ich frage, welche Schildfarbe meinem Team am besten gefällt.","Ich halte den Zugang frei und prüfe eine Regalbeschriftung als Alternative.","Ich mache die Freigabe davon abhängig, dass ein zusätzliches Schild eingesetzt wird.","Ich verschiebe die Beratungsfläche in den Hauptgang, damit das Schild seinen Platz behalten kann."],"why":"Der freie Zugang ist vorgegeben. Die Regalbeschriftung erreicht den Zweck des Schilds, wenn sie verständlich ist. So wird die erste Idee am Fall geprüft und bei Bedarf verändert.","hint":"Was darf dabei auf keinen Fall verloren gehen?","steps":"Vergleiche den Nutzen deiner Idee mit der festen Flächenvorgabe. Prüfe, ob eine andere Lösung denselben Nutzen hat.","example":"Wenn ein Möbel den Hauptgang versperrt, kannst du eine andere Position oder einen anderen Warenträger wählen.","sourceRefs":["M3","M5","M6"],"id":6,"l":1,"type":"multi","caseLabel":"LS 6.1 · Die Nachfrage an zwei Standorten vergleichen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"c":1,"title":"Die erste Idee prüfen","scene":"Sarah schlägt ein gemeinsames Angebot und denselben Aufbau vor. Sebastian zeigt die unterschiedlichen Ladenprofile.","ask":"Welche Gedanken helfen, die erste Idee fair zu prüfen?","answer":[1,3,5],"options":["Die Vorbereitung wird einfacher, also muss derselbe Aufbau überall passen.","Ein gemeinsamer Rahmen für die Aktion und unterschiedliche Aufbauten können zusammenpassen.","Der Vorschlag von Sarah ist durch die unterschiedliche Fläche automatisch in jedem Teil widerlegt.","Ich prüfe die Idee getrennt an Kundenanfragen, Verkaufsform und Platz.","Wenn ich den Vorschlag mag, lasse ich störende Angaben aus der Matrix weg.","Ich halte fest, bei welchem konkreten Beleg ich meine erste Einschätzung ändere."],"why":"Sarahs Idee erleichtert die Vorbereitung. Erst der Vergleich zeigt, welche Teile man gemeinsam planen kann und wo Unterschiede eine eigene Lösung erfordern.","hint":"Unterscheide die Idee einer gemeinsamen Aktion vom identischen Aufbau.","steps":"Nenne den Vorteil der Idee. Prüfe danach pro Laden, wo sie an Grenzen stößt.","example":"Ein gemeinsames Motiv kann erhalten bleiben, wenn ein kleines Geschäft weniger Stellfläche hat.","sourceRefs":["Handlungssituation","M5"],"id":7,"l":1,"type":"multi","caseLabel":"LS 6.1 · Die Nachfrage an zwei Standorten vergleichen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"c":2,"title":"Rückfragen im Team","scene":"Ein Teammitglied möchte für Leer einen gleichen Vorführtisch wie bei Block. Eine andere Person verweist auf die Selbstbedienung in Leer.","ask":"Welche Gesprächsbeiträge bringen euch weiter?","answer":[0,2,4],"options":["Ich frage nach, welchen Vorteil der Tisch in Leer bringen soll.","Ich entscheide allein, weil die Ideen zu verschieden sind.","Ich lege die Angaben zur Verkaufsform nebeneinander.","Ich stimme ab, bevor wir den Standortbeleg anschauen.","Ich erkläre meinen Vorschlag mit der konkreten Ladenbedingung.","Ich streiche den Einwand ohne Rückfrage, weil Block schon einen Tisch hat."],"why":"Mit einer Rückfrage, einem gemeinsamen Blick auf die Daten und einer begründeten eigenen Position klärt ihr, ob der Tisch für Leer sinnvoll wäre.","hint":"Hört euch erst an, welchen Bedarf jede Idee erfüllen soll.","steps":"Vergleicht danach die Begründungen mit der unterschiedlichen Verkaufsform.","example":"Ihr könnt eine Idee weiterentwickeln, indem ihr aus einer persönlichen Vorführung eine leicht verständliche Regalinfo macht.","sourceRefs":["M2","M3","M4"],"id":8,"l":1,"type":"multi","caseLabel":"LS 6.1 · Die Nachfrage an zwei Standorten vergleichen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"c":2,"title":"Für Jan vorbereiten","scene":"Um 10 Uhr kommen beide Läden zur Besprechung. Jan Richter will wissen, welcher Unterschied für die Aktion am wichtigsten ist.","ask":"Welche Beiträge helfen dem Team, zu einer begründeten Einschätzung zu kommen?","answer":[2,4],"options":["Wir reichen zwei ungeprüfte Einzelmeinungen ohne Belege ein.","Wir beschreiben nur den Laden, den wir besser kennen.","Wir vergleichen dieselben Kriterien für beide Läden.","Wir einigen uns allein nach der optisch schönsten Skizze.","Wir erklären, wie sich unser wichtigster Unterschied auf den Aufbau auswirkt.","Wir legen die Anzahl der Regale zugrunde und blenden Beratung und Nachfrage aus."],"why":"Ein Vergleich nach denselben Kriterien zeigt Unterschiede. Für Jan muss daraus erkennbar sein, was diese Unterschiede für die Aktion bedeuten.","hint":"Denke von Jans Entscheidung aus: Was muss er nach eurem Beitrag wissen?","steps":"Nennt euren wichtigsten Unterschied und begründet, welche Folgen er für beide Standorte hat.","example":"Ein unterschiedlicher Bedarf an Beratung kann erklären, warum ein Laden Vorführplatz braucht und der andere klare Regalhinweise.","sourceRefs":["Handlungssituation","M5"],"id":9,"l":1,"type":"multi","caseLabel":"LS 6.1 · Die Nachfrage an zwei Standorten vergleichen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"c":4,"title":"Quelle für den Beleg finden","scene":"Euch liegen Kurzprofile, eine Maßskizze und zwei Sprechtexte zu den Läden vor.","ask":"Welche Quellenwahl passt zur gesuchten Information?","answer":[1,3,4],"options":["Die korrekte Gangbreite übernehme ich aus der Zahl der Anfragen in M1.","Den Bedarf nach Sichtbarkeit bei Block belege ich mit dem Kurzprofil M1.","Die gesamte Ladenfläche verrät, welche Pumpe zu einem Ventil passt.","Für den Stellplatz des Tresens schaue ich in die Skizzenhilfe M3.","Für eine Kundenfrage zur Ventilpassung nutze ich das Kurzprofil M2 oder die Sprachnachricht M4.","Für den Werkstattzugang ist eine allgemeine Definition von Zielgruppe ausreichend."],"why":"Die Kurzprofile und Sprechtexte liefern konkrete Nachfragen. Die Skizzenhilfe enthält Maße und Positionen. Gesucht ist jeweils die Quelle, die genau zur Behauptung passt.","hint":"Kläre zuerst: Suchst du eine Äußerung, eine Zahl oder einen Ort im Plan?","steps":"Vergleiche den Inhalt der Quelle mit der Frage. Eine ähnliche Fragestellung reicht als Beleg nicht aus.","example":"Ein Lageplan zeigt dir, wo ein Tisch steht; ein Nachfrageprotokoll zeigt dir, warum jemand ein Licht sucht.","sourceRefs":["M1","M2","M3","M4"],"id":10,"l":1,"type":"multi","caseLabel":"LS 6.1 · Die Nachfrage an zwei Standorten vergleichen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"c":4,"title":"Kundenstimmen auswerten","scene":"Eine Kundin fragt in Leer, welche Pumpe zu den Ventilen ihrer Familie passt. Ein Kunde bei Block möchte sehen, ob ein Schloss durch seinen Rahmen passt.","ask":"Welche Notizen geben die Stimmen verständlich und angemessen wieder?","answer":[0,2],"options":["Leer: Die Kundin braucht eine leicht auffindbare Angabe zur Ventilart.","Leer: Unsere Pumpen passen garantiert zu allen Ventilen.","Block: Der Kunde will die Passung des Schlosses am eigenen Rad prüfen.","Block: Der Kunde hat ein Schloss bereits gekauft.","Leer: Alle Familien wollen dieselbe Pumpe.","Block: Der Bedarf besteht nur aus einer Frage zum Preis."],"why":"Beide Stimmen belegen einen Wunsch nach Informationen zur Passung. Aus ihnen folgt weder ein Verkauf noch eine Garantie für alle Fahrräder.","hint":"Was wurde gefragt? Was wurde daraus lediglich gefolgert?","steps":"Schreibe den Kern der Aussage in einem Satz auf. Füge keine Eigenschaft hinzu, die im Fall fehlt.","example":"‚Welches Modell passt?‘ ist eine Bitte um Orientierung und keine Bestätigung der Passung.","sourceRefs":["M1","M2"],"id":11,"l":1,"type":"multi","caseLabel":"LS 6.1 · Die Nachfrage an zwei Standorten vergleichen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"c":0,"title":"Beratung sinnvoll einplanen","scene":"Für Block wird ein Tisch vorgeschlagen, an dem die Fachkraft die Lichtbefestigung zeigt. Der Platz ist knapp; Hauptgang und Werkstattzugang müssen frei bleiben.","ask":"Welche Entscheidungen sind durch den Fall begründbar?","answer":[1,4],"options":["Der Tisch steht am besten quer im Hauptgang, damit alle die Vorführung sehen.","Die Fachkraft soll Lichtbefestigung bei Bedarf am Fahrrad zeigen können.","Der Beleg spricht dafür, nur Artikel zu einem festen Preis zu verkaufen.","Der Tisch ist zwingend, selbst wenn der freie Zugang mit ihm schwierig wird.","Vor dem Aufbau prüft ihr, ob auch mit abgestelltem Fahrrad Gang und Zugang frei bleiben.","Die Lichtberatung wird ausschließlich an die Information in Leer verwiesen."],"why":"Die Kundenstimme stützt die Demonstration. Die konkrete Lösung muss das Fahrrad einplanen und die Verkehrswege freihalten. Der Tisch selbst ist damit keine Pflicht.","hint":"Unterscheide das Ziel der Beratung vom vorgeschlagenen Möbel.","steps":"Lies die Kundenstimme und prüfe anschließend, welche Platzvorgabe auch beim Einsatz eingehalten werden muss.","example":"Eine kurze Vorführung kann je nach Fläche auch ohne zusätzlichen Tisch gelingen.","sourceRefs":["M1","M3"],"id":12,"l":2,"type":"multi","caseLabel":"LS 6.1 · Die Nachfrage an zwei Standorten vergleichen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"c":0,"title":"Selbstbedienung ermöglichen","scene":"In Leer möchte eine Familie eine Pumpe für ihre Ventile finden. Samstags ist niemand fest für die Beratung auf der Aktionsfläche eingeteilt.","ask":"Welche Maßnahmen greifen beide Fallinformationen auf?","answer":[0,3,5],"options":["Die Ventilarten werden auf dem Regalschild verständlich genannt.","Ihr verspricht, dass jedes Produkt ohne Prüfung zu allen Fahrrädern passt.","Ihr schreibt nur ‚Aktion‘ aufs Schild und legt alle Pumpen ohne erkennbare Ordnung zusammen.","Die verfügbaren Pumpen werden nach gut sichtbaren Merkmalen vergleichbar angeordnet.","Ihr plant stattdessen voraus, dass die Fachkraft jede Familie bis zum Regal begleitet.","Falls jemand unsicher bleibt, weist ihr auf die Information hin."],"why":"Die Beschriftung und geordnete Auswahl helfen beim Selberfinden. Ein Hinweis auf die Information deckt offene Fragen ab, ohne dauerhaft besetzte Beratung vorauszusetzen.","hint":"Was muss man selbst erkennen können, bevor man nachfragen muss?","steps":"Prüfe den Anfang der Suche, den Produktvergleich und den Weg bei einer offenen Frage.","example":"Ein Merkmal wie die passende Ventilart hilft mehr als ein Schild, auf dem nur ‚Angebot‘ steht.","sourceRefs":["M2","M4"],"id":13,"l":2,"type":"multi","caseLabel":"LS 6.1 · Die Nachfrage an zwei Standorten vergleichen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"c":0,"title":"Sortiment oder Präsentation","scene":"In der Vergleichsmatrix müsst ihr erkennen lassen, ob es um die Warenauswahl oder um den Aufbau geht.","ask":"Welche Aussagen sind Anforderungen an die Präsentation?","answer":[0,2,4],"options":["Ordnet Pannenzubehör in einem gut auffindbaren Bereich an.","Wählt Zubehör zum sicheren Abstellen für Block aus.","Beschriftet die Ventilarten am Regal deutlich.","Nehmt passende Lichter für Fahrten bei Dunkelheit ins Angebot auf.","Richtet einen Vorführbereich ein, ohne den Werkstattzugang zu versperren.","Wählt für Leer Zubehör für Familienausflüge aus."],"why":"Anordnung, Beschriftung und Vorführbereich betreffen, wie die Ware gezeigt wird. Die anderen Vorschläge legen fest, welche Ware angeboten wird.","hint":"Achte auf die Frage: Was wird verkauft oder wie wird es gezeigt?","steps":"Ordne jeden Vorschlag einer der beiden Fragen zu und prüfe, ob er zugleich einen Ladenbezug enthält.","example":"Ein Pumpenmodell auszuwählen betrifft das Sortiment. Es nach Ventilart zu beschriften betrifft die Präsentation.","sourceRefs":["M5"],"id":14,"l":2,"type":"multi","caseLabel":"LS 6.1 · Die Nachfrage an zwei Standorten vergleichen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"c":3,"title":"Flächenplan kontrollieren","scene":"Die Aktionsfläche für Leer misst 6,40 m × 3,50 m. Eine Gondel misst 1,60 m × 0,60 m. Ihr zeichnet im Maßstab 1:25.","ask":"Welche Maße gehören in euren Plan?","answer":[1,3],"options":["Die Aktionsfläche ist 22,4 cm × 14,0 cm groß.","Die Aktionsfläche ist 25,6 cm × 14,0 cm groß.","Eine Gondel ist 4,0 cm × 1,6 cm groß.","Eine Gondel ist 6,4 cm × 2,4 cm groß.","Eine Gondel ist 16,0 cm × 6,0 cm groß.","Der Maßstab wird nur auf die Aktionsfläche angewendet; die Gondeln bleiben in Originalgröße."],"why":"640 ÷ 25 = 25,6 und 350 ÷ 25 = 14. Bei der Gondel führen 160 ÷ 25 und 60 ÷ 25 zu 6,4 cm × 2,4 cm.","hint":"Verwende für jeden einzelnen Längenwert dieselbe Rechnung.","steps":"Wandle Meter in Zentimeter um. Teile anschließend alle vier Zahlen durch 25.","example":"1,00 m werden bei 1:25 zu 4,0 cm. Länge und Tiefe werden einzeln umgerechnet.","sourceRefs":["M3"],"id":15,"l":2,"type":"multi","caseLabel":"LS 6.1 · Die Nachfrage an zwei Standorten vergleichen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"c":3,"title":"Flächen fair vergleichen","scene":"Block hat 3,60 m × 3,20 m. Die Bike Arena hat 6,40 m × 3,50 m. Der feste Beratungstresen steht innerhalb der Fläche bei Block. Die angrenzenden Hauptgänge bleiben frei.","ask":"Welche Schlussfolgerungen sind richtig?","answer":[0,1,5],"options":["Die rechteckige Aktionsfläche bei Block misst rechnerisch 11,52 m².","Die rechteckige Aktionsfläche in Leer misst rechnerisch 22,40 m².","Der Hauptgang darf in beiden Läden zur Aktionsfläche hinzugerechnet und belegt werden.","Da 6,40 m weniger als doppelt so lang wie 3,60 m sind, haben beide Läden gleich viel Platz.","Die gesamten 11,52 m² bei Block stehen für bewegliche Aktionsmöbel frei.","Die Rechteckfläche allein reicht nicht, um den Aufbau mit dem Tresen und allen Wegen zu beurteilen."],"why":"Die beiden Rechtecke sind unterschiedlich groß. Der Tresen bindet bei Block einen Teil des Platzes. Außerdem dürfen angrenzende Gänge nicht verstellt werden.","hint":"Vergleiche Fläche und tatsächlich nutzbaren Platz.","steps":"Berechne pro Laden Länge × Breite. Prüfe anschließend die festen Hindernisse und Zugänge.","example":"Eine Fläche von 4 m × 3 m hat 12 m². Ein festes Möbel verändert die nutzbare Anordnung, obwohl das Rechteck gleich groß bleibt.","sourceRefs":["M3"],"id":16,"l":2,"type":"multi","caseLabel":"LS 6.1 · Die Nachfrage an zwei Standorten vergleichen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"c":1,"title":"Zahlen nicht überdeuten","scene":"In einem Entwurf steht: ‚Bei Block ist Licht das häufigste Hauptanliegen. Deshalb will fast die ganze Kundschaft Licht kaufen.‘","ask":"Wie machst du die Aussage belastbar?","answer":[1,3],"options":["Schreibe ‚neun Verkäufe‘ statt ‚fast die ganze Kundschaft‘.","Nenne neun von 20 erfassten Anfragen zur Sichtbarkeit auf dem Arbeitsweg.","Weite den Befund auf alle Kundinnen und Kunden im Jahresverlauf aus.","Nutze den Befund als Hinweis für die Warenauswahl in dieser Aktion.","Behaupte, dass die restlichen elf Anfragen bei Leer erfasst wurden.","Streiche alle Nachfragedaten, weil sie die Zukunft nicht sicher vorhersagen."],"why":"Die 20 Anfragen sind eine begrenzte Beobachtung. Neun sprechen für Sichtbarkeit als wichtigen Bedarf, belegen aber keine Kaufentscheidung der gesamten Kundschaft.","hint":"Welche Gruppe und welcher Zeitraum stehen tatsächlich im Fall?","steps":"Ersetze große Behauptungen durch die Zahl, den Standort und das gezählte Anliegen.","example":"Ein hoher Anteil in einer erfassten Stichprobe ist ein Auswahlhinweis. Eine sichere Prognose ist es nicht.","sourceRefs":["M1"],"id":17,"l":2,"type":"multi","caseLabel":"LS 6.1 · Die Nachfrage an zwei Standorten vergleichen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"c":1,"title":"Priorität korrigieren","scene":"Dein erster Entwurf nennt ein zusätzliches Schild bei Leer zwingend und freie Gondelseiten wünschenswert. M3 sieht Ware auf beiden Seiten vor; die Vorder- und Rückseite sollen erreichbar bleiben.","ask":"Was verbesserst du?","answer":[2,3,5],"options":["Ich halte an der Einordnung fest, weil mein Entwurf schon fertig ist.","Ich streiche beide Punkte und plane eine größere Verkaufsfläche.","Ich halte den Zugang zu beiden Warenseiten als notwendige Aufbauvorgabe fest.","Ich prüfe, ob eine gute Regalbeschriftung das zusätzliche Schild ersetzen kann.","Ich erkläre das Schild in jedem Fall zur Pflicht, weil Leer mehr Platz hat.","Ich vermerke, welche Fallangabe meine ursprüngliche Reihenfolge geändert hat."],"why":"Die beidseitige Erreichbarkeit trägt hier die Selbstbedienung. Ein separates Schild ist nur eine von mehreren Möglichkeiten, die Ware zu kennzeichnen.","hint":"Frage bei jedem Punkt: Was wäre verloren, wenn wir ihn weglassen?","steps":"Vergleiche den Zweck der Vorgabe mit möglichen gleichwertigen Alternativen.","example":"Ein Regalzugang hängt vom Aufbau ab. Die Beschriftung kann am Regal oder auf einem nahen Schild stehen.","sourceRefs":["M3","M4","M5"],"id":18,"l":2,"type":"multi","caseLabel":"LS 6.1 · Die Nachfrage an zwei Standorten vergleichen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"c":2,"title":"Eine Rückmeldung schreiben","scene":"Eine andere Gruppe notiert bei Leer: ‚Pumpen neben den Hauptgang stellen. Das ist gut.‘ Ihr gebt Feedback zur Vergleichsmatrix.","ask":"Welche Rückmeldungen helfen bei der Überarbeitung?","answer":[0,2,4],"options":["Ergänzt die Kundenfrage zur Ventilpassung als Beleg für eine klare Beschriftung.","Die Idee ist schlecht, weil uns Pumpen nicht interessieren.","Erklärt, wie der Hauptgang bei diesem Standort frei bleibt.","Schreibt einfach, dass die gesamte Idee zwingend ist.","Unterscheidet bei Bedarf die Warenauswahl von der Platzierung.","Nehmt den Vorschlag unverändert, weil darin schon der Standort vorkommt."],"why":"Die Rückmeldungen fordern Belege und prüfen eine konkrete Vorgabe. Sie zeigen außerdem, wo sich Entscheidungen über Ware und Aufbau vermischen.","hint":"Was fehlt im Satz, damit Jan handeln kann?","steps":"Nenne eine beobachtbare Verbesserung und knüpfe sie an einen Beleg oder ein Feld der Matrix.","example":"Statt ‚schöner machen‘ hilft ‚Beschrifte die Ventilarten so, dass sie am Regal lesbar sind‘.","sourceRefs":["M2","M3","M5"],"id":19,"l":2,"type":"multi","caseLabel":"LS 6.1 · Die Nachfrage an zwei Standorten vergleichen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"c":2,"title":"Im Pitch begründen","scene":"Eine Teamkollegin möchte im kurzen Pitch nur aufzählen, welche Waren beide Läden zeigen. Jan fragte nach dem wichtigsten Unterschied und seiner Folge.","ask":"Welche Ergänzungen sollen in den Pitch?","answer":[1,3],"options":["Ein langer Bericht darüber, wie die Gruppe abgestimmt hat.","Ein Beispiel dafür, wie persönliche Beratung bei Block den Aufbau verändert.","Nur die Zahl der Beteiligten aus beiden Läden.","Ein Beispiel dafür, wie Kundinnen und Kunden in Leer beim Selbstfinden unterstützt werden.","Die pauschale Aussage, dass Leer in allen Bereichen besser ist.","Ein unbelegtes Versprechen, dass der Aufbau Verkaufszahlen garantiert steigert."],"why":"Zwei Beispiele zu derselben Verkaufsfrage zeigen, warum sich die Aufbauten unterscheiden. Die Beispiele müssen am Fall überprüfbar sein.","hint":"Nenne die praktische Folge eines Unterschieds für jeden Laden.","steps":"Wähle je eine kurze Beobachtung. Verbinde sie mit einer konkreten Anforderung.","example":"‚Werkstattzugang und Platz am Beratungsort‘ ist für Jan greifbarer als ‚Block braucht einen anderen Aufbau‘.","sourceRefs":["Handlungssituation","M1","M2","M5"],"id":20,"l":2,"type":"multi","caseLabel":"LS 6.1 · Die Nachfrage an zwei Standorten vergleichen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"c":4,"title":"Beleg und Anforderung verbinden","scene":"In der digitalen Matrix steht in einer Zelle nur ‚M3‘. Der Vorschlag lautet: ‚Den Durchgang bei Block frei halten.‘","ask":"Welche Ergänzungen machen den Eintrag prüfbar?","answer":[0,3,5],"options":["Notiere, dass der 1,20 m breite Hauptdurchgang zum Werkstattzugang führt.","Verlinke die Quelle, ohne die relevante Information im Ergebnis zu nennen.","Belege die Gangbreite mit einer ungeprüften Erinnerung aus einem anderen Laden.","Ordne die betroffene Zeile Block zu und gib M3 als Quelle an.","Ersetze das Maß durch die Angabe ‚gefühlt breit genug‘.","Kennzeichne, dass der Zugang laut Flächenvorgabe frei bleiben muss."],"why":"Eine konkrete Angabe zeigt, welche Stelle in M3 den Vorschlag trägt. Standort, Quelle, Maß und Verpflichtung müssen zusammen erkennbar bleiben.","hint":"Eine Quellen-ID allein verrät noch nicht, welche Angabe gemeint ist.","steps":"Trage Nummer der Quelle und die belegende Einzelangabe in die passende Zeile ein.","example":"‚M3, Hauptdurchgang 1,20 m‘ ist genauer als ‚M3, Platz‘.","sourceRefs":["M3","M5"],"id":21,"l":2,"type":"multi","caseLabel":"LS 6.1 · Die Nachfrage an zwei Standorten vergleichen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"c":4,"title":"Skizze und Sprachnachricht abgleichen","scene":"Eine Sprachnachricht nennt für Leer einen Hauptgang an der langen Seite. Eure Skizze zeigt den Gang an der kurzen Seite. M3 enthält die Skizzenhilfe.","ask":"Welche Überarbeitung ist fachlich sauber?","answer":[2,3,5],"options":["Passt die Nachricht an eure Skizze an und gebt sie als Original wieder.","Lasst den Gang an der kurzen Seite, wenn das auf dem Blatt besser aussieht.","Vergleicht den Sprechtext mit der Skizzenhilfe und korrigiert die Lage in eurer Zeichnung.","Tragt den Gang an der 6,40 m langen Seite ein.","Verzichtet auf den Lagehinweis, weil das Flächenmaß ohnehin stimmt.","Prüft, ob geänderte Regalpositionen den Zugang und die Gondelseiten frei lassen."],"why":"Sprechtext und M3 zeigen dieselbe Lage. Die Zeichnung wird daran angepasst und die Position der betroffenen Möbel danach erneut geprüft.","hint":"Der Fehler betrifft die Lage und kann Folgen für den Aufbau haben.","steps":"Sucht zuerst die lange Seite. Prüft dann, was sich für Zugang und Erreichbarkeit der Regale ändert.","example":"Eine Skizze kann die richtigen Gesamtmaße enthalten und trotzdem den Gang an der falschen Stelle zeigen.","sourceRefs":["M3","M4"],"id":22,"l":2,"type":"multi","caseLabel":"LS 6.1 · Die Nachfrage an zwei Standorten vergleichen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"c":0,"title":"Eine Empfehlung für beide Standorte","scene":"Jan fragt, ob für beide Geschäfte genau derselbe Aufbau freigegeben werden soll. Er will die Vorbereitung einfach halten und gleichzeitig, dass die Aktion in beiden Läden funktioniert.","ask":"Welche Aussagen könnt ihr fachlich gut vertreten?","answer":[1,4],"options":["Die größere Aktionsfläche in Leer macht Beratung bei Block überflüssig.","Ein gemeinsames Aktionsmotiv ist denkbar; der Aufbau muss an Verkaufsform und Platz je Laden angepasst werden.","Da in beiden Läden 20 Anfragen erfasst wurden, haben sie dieselbe Zielgruppe.","Für Block reicht die Planung anhand des Beratungstresens. Kundenanfragen spielen für die Auswahl keine Rolle.","Zwingende Vorgaben wie freie Wege prüft ihr für jeden Standort vor der Freigabe.","Einen gemeinsamen Aufbau kann man freigeben, sobald er im größeren Laden passt."],"why":"Ein gemeinsamer Rahmen lässt sich mit standortgerechten Flächen verbinden. Gleiche Fallzahlen bedeuten keine identischen Bedürfnisse. Beide Aufbauten müssen ihre Vorgaben erfüllen.","hint":"Sucht zuerst Gemeinsamkeiten. Prüft danach jede Bedingung, die je Laden anders ist.","steps":"Vergleicht pro Standort Nachfrage, Verkaufsform und Fläche. Formuliert, was gleich aussehen kann und was geprüft werden muss.","example":"Zwei Läden können dasselbe Aktionsthema nutzen und unterschiedliche Warenträger einsetzen.","sourceRefs":["Handlungssituation","M1","M2","M3","M5"],"id":23,"l":2,"type":"multi","caseLabel":"LS 6.1 · Die Nachfrage an zwei Standorten vergleichen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"c":0,"title":"Den Vergleich beginnen","scene":"Übungsvariante: Für das Treffen um 10 Uhr bleibt wenig Zeit. Sarah würde gern denselben Aufbau vorbereiten. Jan bittet dich um eine kurze, belastbare Empfehlung für Aurich und Leer.","ask":"Womit beginnst du?","options":["Ich markiere je Laden eine Kundenaussage und die passenden Angaben zur Verkaufsform.","Ich sammle je Laden eine Rückfrage, die sich mit dem Verkaufsteam klären lässt.","Ich markiere im Plan die Bereiche, die zwingend frei bleiben müssen.","Ich vergleiche beide Kurzprofile in drei Spalten: Nachfrage, Verkaufsform und Fläche.","Ich frage die Ladenvertretungen, wie Kundinnen und Kunden vor Ort am besten durch die Aktion finden.","Ich notiere je Laden die feste Ausstattung und den nutzbaren Zugang als erste Planungsgrenzen."],"consequences":["Zwei beobachtete Kaufanlässe werden zum Ausgangspunkt deines Vergleichs.","Du gehst mit einer klaren Frage an beide Läden in die Vorbereitung.","Die freien Wege stehen fest, bevor du Möbel einplanst.","Die Belege lassen sich nach denselben Kriterien prüfen.","Du startest mit der Erfahrung der Menschen, die den Aufbau nutzen.","Die begrenzenden Maße und Warenträger sind markiert."],"sourceRefs":["Handlungssituation","M1","M2","M3"],"hint":"Überlege, welche Perspektive du bisher für die Empfehlung genutzt hast.","steps":"Lies die neue Information. Wähle, wie du sie mit deinem bisherigen Schwerpunkt verbindest.","example":"Eine Änderung im Plan kann am besten über einen neuen Beleg, eine Rückfrage oder die Prüfung einer Vorgabe erklärt werden.","why":"Die Rückmeldung zeigt, wie deine sechs Entscheidungen zusammenpassen.","id":24,"l":3,"type":"story","caseLabel":"LS 6.1 · Die Nachfrage an zwei Standorten vergleichen","storyIndex":0,"logicMap":[0,1,2,0,1,2],"logicRoles":["Belegweg","Beteiligungsweg","Rahmenweg","Belegweg","Beteiligungsweg","Rahmenweg"],"criteria":"Wähle eine Handlung. Am Ende siehst du, wie deine sechs Entscheidungen zusammenpassen."},{"c":3,"title":"Zwei Vorschläge eingrenzen","scene":"Übungsvariante: Sarah skizziert einen gemeinsamen Vorführtisch. Als Alternative schlägt Sebastian für Block einen Beratungsplatz und für Leer eine gut beschriftete Selbstbedienungsfläche vor.","ask":"Wie vergleichst du beide Vorschläge?","options":["Ich halte pro Vorschlag fest, welche Kundenstimme und welche Verkaufsform dafür sprechen.","Ich bitte beide Läden um Rückmeldung dazu, wie die Kundschaft bei jedem Vorschlag Hilfe bekommt.","Ich prüfe beide Vorschläge zuerst an den Gang- und Zugangsmaßen.","Ich vergleiche anhand von M1 und M2, welche Anfrage jede Variante abdeckt und wo Belege fehlen.","Ich kläre mit der Fachkraft bei Block und der Information in Leer, was sie beim Aufbau leisten können.","Ich zeichne beide Varianten grob ein und markiere Engstellen um Tresen, Gondeln und Wege."],"consequences":["Du kannst zeigen, welche Fallangabe für welchen Entwurf spricht.","Mögliche Lücken aus Sicht der Ladenvertretungen werden sichtbar.","Unpassende Möbelpositionen fallen schon vor der weiteren Planung auf.","Deine Vergleichszeilen trennen belegte Bedürfnisse von offenen Punkten.","Die Aufgaben der Beschäftigten sind vorläufig geklärt.","Die beiden Skizzen zeigen klar, wo der Platz knapp wird."],"sourceRefs":["M1","M2","M3"],"hint":"Überlege, welche Perspektive du bisher für die Empfehlung genutzt hast.","steps":"Lies die neue Information. Wähle, wie du sie mit deinem bisherigen Schwerpunkt verbindest.","example":"Eine Änderung im Plan kann am besten über einen neuen Beleg, eine Rückfrage oder die Prüfung einer Vorgabe erklärt werden.","why":"Die Rückmeldung zeigt, wie deine sechs Entscheidungen zusammenpassen.","id":25,"l":3,"type":"story","caseLabel":"LS 6.1 · Die Nachfrage an zwei Standorten vergleichen","storyIndex":1,"logicMap":[0,1,2,0,1,2],"logicRoles":["Belegweg","Beteiligungsweg","Rahmenweg","Belegweg","Beteiligungsweg","Rahmenweg"],"criteria":"Wähle eine Handlung. Am Ende siehst du, wie deine sechs Entscheidungen zusammenpassen.","branchFrom":24,"branchText":["Beziehe die Angaben, die du gerade geprüft hast, in deine nächste Entscheidung ein.","Berücksichtige, wessen Rückmeldung oder Sichtweise du gerade aufgenommen hast.","Beachte bei deiner nächsten Entscheidung die Vorgabe oder Grenze, die du gerade geklärt hast.","Beziehe die Angaben, die du gerade geprüft hast, in deine nächste Entscheidung ein.","Berücksichtige, wessen Rückmeldung oder Sichtweise du gerade aufgenommen hast.","Beachte bei deiner nächsten Entscheidung die Vorgabe oder Grenze, die du gerade geklärt hast."]},{"c":0,"title":"Eine neue Bedingung prüfen","scene":"Übungsvariante: Block meldet kurz vor dem Termin, dass für einen Teil des Vormittags zusätzliche Räder zur Werkstatt geschoben werden. Der Hauptgang bleibt frei. Der Entwurf muss auf diese Nutzung reagieren.","ask":"Wie arbeitest du die Nachricht ein?","options":["Ich ergänze die Nachricht als neuen Beleg und prüfe, welche Zeile zum Aufbau angepasst werden muss.","Ich frage das Block-Team, an welcher Stelle beim Schieben der Räder die geplante Beratung stören könnte.","Ich prüfe die freie Wegbreite im Plan und halte den zusätzlichen Verkehr als Aufbaugrenze fest.","Ich ergänze die Werkstattmeldung in der Vergleichsmatrix neben der ursprünglichen Flächenvorgabe.","Ich bespreche mit Beratung und Werkstatt, wie die Vorführung daneben ohne Behinderung stattfinden kann.","Ich prüfe zwei Tischpositionen und verwerfe jede, bei der Fahrrad oder Beratung in den Durchgang geraten."],"consequences":["Jede Änderung bleibt auf die neue Information zurückführbar.","Die Antwort aus dem Laden kann eine konkrete Engstelle zeigen.","Du schützt den verpflichtenden Durchgang auch bei mehr Betrieb.","Alter und neuer Nachweis sind klar voneinander zu unterscheiden.","Die betroffenen Beschäftigten bringen ihre Arbeitsabläufe in den Entwurf ein.","Du behältst nur Positionen, die sich auch im Betrieb einrichten lassen."],"sourceRefs":["M1","M3","M5"],"hint":"Überlege, welche Perspektive du bisher für die Empfehlung genutzt hast.","steps":"Lies die neue Information. Wähle, wie du sie mit deinem bisherigen Schwerpunkt verbindest.","example":"Eine Änderung im Plan kann am besten über einen neuen Beleg, eine Rückfrage oder die Prüfung einer Vorgabe erklärt werden.","why":"Die Rückmeldung zeigt, wie deine sechs Entscheidungen zusammenpassen.","id":26,"l":3,"type":"story","caseLabel":"LS 6.1 · Die Nachfrage an zwei Standorten vergleichen","storyIndex":2,"logicMap":[0,1,2,0,1,2],"logicRoles":["Belegweg","Beteiligungsweg","Rahmenweg","Belegweg","Beteiligungsweg","Rahmenweg"],"criteria":"Wähle eine Handlung. Am Ende siehst du, wie deine sechs Entscheidungen zusammenpassen.","branchFrom":25,"branchText":["Beziehe die Angaben, die du gerade geprüft hast, in deine nächste Entscheidung ein.","Berücksichtige, wessen Rückmeldung oder Sichtweise du gerade aufgenommen hast.","Beachte bei deiner nächsten Entscheidung die Vorgabe oder Grenze, die du gerade geklärt hast.","Beziehe die Angaben, die du gerade geprüft hast, in deine nächste Entscheidung ein.","Berücksichtige, wessen Rückmeldung oder Sichtweise du gerade aufgenommen hast.","Beachte bei deiner nächsten Entscheidung die Vorgabe oder Grenze, die du gerade geklärt hast."]},{"c":2,"title":"Leer mitdenken","scene":"Übungsvariante: Die Ladenvertretung aus Leer will, dass die Kundschaft Ventiltypen leicht erkennt. Samstags bleibt die Aktionsfläche wie im Ausgangsfall ohne feste Beratung.","ask":"Wie legst du den nächsten Schritt für Leer fest?","options":["Ich leite aus der Frage der Familie eine prüfbare Anforderung an die Regalbeschriftung ab.","Ich bitte die Information um eine Rückmeldung, an welcher Angabe Kundinnen und Kunden oft scheitern.","Ich plane Regalhinweise so ein, dass Warenseiten und Hauptgang frei bleiben.","Ich verknüpfe in der Matrix die Kundenstimme mit der fehlenden festen Beratung als Begründung.","Ich lasse eine Person aus dem Team die Pumpenwahl aus Kundensicht ausprobieren.","Ich prüfe, ob ein freistehender Schildhalter in den Plan passt und andernfalls eine Regalbeschriftung genügt."],"consequences":["Die Beschriftung lässt sich an einer konkreten Kaufanfrage prüfen.","Der Vorschlag berücksichtigt die Erfahrung der Anlaufstelle.","Die Information bleibt auffindbar und die Wege bleiben nutzbar.","Jan kann die Entscheidung aus zwei Fallangaben nachvollziehen.","Das Team bekommt direkte Rückmeldung zum Selberfinden.","Du hast zwei realistische Kennzeichnungsvarianten für den verfügbaren Platz."],"sourceRefs":["M2","M3","M4","M5"],"hint":"Überlege, welche Perspektive du bisher für die Empfehlung genutzt hast.","steps":"Lies die neue Information. Wähle, wie du sie mit deinem bisherigen Schwerpunkt verbindest.","example":"Eine Änderung im Plan kann am besten über einen neuen Beleg, eine Rückfrage oder die Prüfung einer Vorgabe erklärt werden.","why":"Die Rückmeldung zeigt, wie deine sechs Entscheidungen zusammenpassen.","id":27,"l":3,"type":"story","caseLabel":"LS 6.1 · Die Nachfrage an zwei Standorten vergleichen","storyIndex":3,"logicMap":[0,1,2,0,1,2],"logicRoles":["Belegweg","Beteiligungsweg","Rahmenweg","Belegweg","Beteiligungsweg","Rahmenweg"],"criteria":"Wähle eine Handlung. Am Ende siehst du, wie deine sechs Entscheidungen zusammenpassen.","branchFrom":26,"branchText":["Beziehe die Angaben, die du gerade geprüft hast, in deine nächste Entscheidung ein.","Berücksichtige, wessen Rückmeldung oder Sichtweise du gerade aufgenommen hast.","Beachte bei deiner nächsten Entscheidung die Vorgabe oder Grenze, die du gerade geklärt hast.","Beziehe die Angaben, die du gerade geprüft hast, in deine nächste Entscheidung ein.","Berücksichtige, wessen Rückmeldung oder Sichtweise du gerade aufgenommen hast.","Beachte bei deiner nächsten Entscheidung die Vorgabe oder Grenze, die du gerade geklärt hast."]},{"c":4,"title":"Die Matrix prüfen","scene":"Übungsvariante: Beide Vorschläge sind ausgearbeitet. Jan sieht die Matrix gleich zum ersten Mal. In ihr müssen Anforderung, Beleg und Priorität schnell auffindbar sein.","ask":"Welche Abschlussprüfung schließt an deinen Weg an?","options":["Ich kontrolliere für jede Anforderung, ob die angegebene Quelle genau diese Aussage stützt.","Ich lasse das Team je eine Rückfrage zu Aurich und Leer aus Sicht der Ladenvertretung formulieren.","Ich prüfe jede Muss-Vorgabe und markiere, wo im jeweiligen Plan sie überprüfbar ist.","Ich ergänze die konkrete Zahl, das Maß oder die wörtliche Kundenfrage, wenn bisher nur eine Quelle genannt ist.","Ich hole eine gezielte Rückmeldung dazu ein, ob beim Lesen wichtige Gründe unklar bleiben.","Ich trenne die zwingenden Punkte von optionalen Verbesserungen und prüfe die umsetzbare Mindestfassung."],"consequences":["Die Belegkette ist pro Zeile nachvollziehbar.","Du erkennst, wo Jan oder die Läden eine verständlichere Begründung brauchen.","Zwingende Vorgaben sind im Ergebnis klar mit dem Aufbau verbunden.","Die Quellenhinweise führen zu überprüfbaren Einzelangaben.","Das Team kann eine unklare Stelle vor dem Treffen präzisieren.","Die Empfehlung bleibt auch bei wenig Platz oder Zeit realistisch."],"sourceRefs":["M3","M5"],"hint":"Überlege, welche Perspektive du bisher für die Empfehlung genutzt hast.","steps":"Lies die neue Information. Wähle, wie du sie mit deinem bisherigen Schwerpunkt verbindest.","example":"Eine Änderung im Plan kann am besten über einen neuen Beleg, eine Rückfrage oder die Prüfung einer Vorgabe erklärt werden.","why":"Die Rückmeldung zeigt, wie deine sechs Entscheidungen zusammenpassen.","id":28,"l":3,"type":"story","caseLabel":"LS 6.1 · Die Nachfrage an zwei Standorten vergleichen","storyIndex":4,"logicMap":[0,1,2,0,1,2],"logicRoles":["Belegweg","Beteiligungsweg","Rahmenweg","Belegweg","Beteiligungsweg","Rahmenweg"],"criteria":"Wähle eine Handlung. Am Ende siehst du, wie deine sechs Entscheidungen zusammenpassen.","branchFrom":27,"branchText":["Beziehe die Angaben, die du gerade geprüft hast, in deine nächste Entscheidung ein.","Berücksichtige, wessen Rückmeldung oder Sichtweise du gerade aufgenommen hast.","Beachte bei deiner nächsten Entscheidung die Vorgabe oder Grenze, die du gerade geklärt hast.","Beziehe die Angaben, die du gerade geprüft hast, in deine nächste Entscheidung ein.","Berücksichtige, wessen Rückmeldung oder Sichtweise du gerade aufgenommen hast.","Beachte bei deiner nächsten Entscheidung die Vorgabe oder Grenze, die du gerade geklärt hast."]},{"c":1,"title":"Die Entscheidung empfehlen","scene":"Übungsvariante: Jan fragt im Treffen, warum sich die Aufbauten unterscheiden sollen, obwohl ein gemeinsames Motiv Zeit spart. Für eure Antwort habt ihr etwa eine Minute.","ask":"Wie fasst du deine Empfehlung zusammen?","options":["Ich nenne je Laden einen Beleg zur Verkaufsform und die praktische Folge für den Aufbau.","Ich fasse die Anforderungen beider Ladenvertretungen zusammen und benenne die gemeinsame Lösungsidee.","Ich erkläre zuerst die beiden Aufbaugrenzen und dann, welche Gestaltung je Laden darin möglich ist.","Ich zeige eine belegte Vergleichszeile je Standort und leite daraus die Empfehlung ab.","Ich verknüpfe je eine Rückmeldung aus Beratung und Selbstbedienung mit unserer Empfehlung.","Ich nenne die zwingenden Vorgaben und erläutere, welche Teile des gemeinsamen Motivs trotzdem umgesetzt werden können."],"consequences":["Jan bekommt zwei nachvollziehbare Belege und eine begründete Empfehlung.","Die Empfehlung zeigt, warum beide Ladenteams mit der Entscheidung arbeiten können.","Die Empfehlung ist mit den örtlichen Grenzen verbunden.","Jan kann die Argumente in der schriftlichen Matrix direkt wiederfinden.","Die unterschiedlichen Arbeitsweisen bleiben in der Entscheidung sichtbar.","Jan weiß, was für die Umsetzung unverzichtbar ist und wo Spielraum bleibt."],"sourceRefs":["Handlungssituation","M1","M2","M3","M5"],"hint":"Überlege, welche Perspektive du bisher für die Empfehlung genutzt hast.","steps":"Lies die neue Information. Wähle, wie du sie mit deinem bisherigen Schwerpunkt verbindest.","example":"Eine Änderung im Plan kann am besten über einen neuen Beleg, eine Rückfrage oder die Prüfung einer Vorgabe erklärt werden.","why":"Die Rückmeldung zeigt, wie deine sechs Entscheidungen zusammenpassen.","id":29,"l":3,"type":"story","caseLabel":"LS 6.1 · Die Nachfrage an zwei Standorten vergleichen","storyIndex":5,"logicMap":[0,1,2,0,1,2],"logicRoles":["Belegweg","Beteiligungsweg","Rahmenweg","Belegweg","Beteiligungsweg","Rahmenweg"],"criteria":"Wähle eine Handlung. Am Ende siehst du, wie deine sechs Entscheidungen zusammenpassen.","branchFrom":28,"branchText":["Beziehe die Angaben, die du gerade geprüft hast, in deine nächste Entscheidung ein.","Berücksichtige, wessen Rückmeldung oder Sichtweise du gerade aufgenommen hast.","Beachte bei deiner nächsten Entscheidung die Vorgabe oder Grenze, die du gerade geklärt hast.","Beziehe die Angaben, die du gerade geprüft hast, in deine nächste Entscheidung ein.","Berücksichtige, wessen Rückmeldung oder Sichtweise du gerade aufgenommen hast.","Beachte bei deiner nächsten Entscheidung die Vorgabe oder Grenze, die du gerade geklärt hast."]},{"title":"Anfrage oder Kauf?","scene":"Block hält sechs Fragen zum sicheren Abstellen fest.","ask":"Welche Aussagen stehen damit fest?","options":["Sechsmal wurde sicheres Abstellen angesprochen.","Genau sechs Schlösser wurden gekauft.","Alle sechs Personen stellten ihr Fahrrad am Bahnhof ab.","Der Laden hat einen Hinweis auf Bedarf an sicherem Abstellen.","Jede dritte Anfrage betraf das sichere Abstellen.","Belegt ist die Nachfrage nach einem bestimmten Schlossmodell."],"answer":[0,3],"why":"Die sechs Einträge belegen Fragen zum sicheren Abstellen. Sie nennen weder Käufe noch ein bestimmtes Modell. Sechs von 20 sind weniger als ein Drittel.","hint":"Prüfe das Verb in der Fallangabe.","steps":"Markiere, was erfasst wurde. Suche danach die Aussagen, die dabei bleiben.","example":"Eine Frage nach dem Preis ist noch kein Kaufbeleg.","id":30,"coreId":0,"reserveNo":1,"type":"multi","l":1,"c":0,"caseLabel":"LS 6.1 · Die Nachfrage an zwei Standorten vergleichen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M1"]},{"title":"Neue Anfragen auswerten","scene":"Übungsvariante: Block erfasst an einem anderen Tag zwölf Anfragen. Sieben betreffen Licht, drei Schlösser und zwei Taschen. Es werden keine Käufe erfasst.","ask":"Welche Aussagen kannst du in den Bericht aufnehmen?","options":["Drei Schlösser wurden verkauft.","Licht wurde häufiger als die beiden anderen Themen zusammen angesprochen.","Die Hälfte der Anfragen betrifft Taschen.","Taschen sind mit zwei Anfragen belegt.","Für jedes Thema wurden gleich viele Personen beraten.","Schlösser und Taschen sind zusammen mit sieben Fragen belegt."],"answer":[1,3],"why":"Sieben Lichtanfragen übertreffen fünf Anfragen zu den beiden anderen Themen. Zwei Anfragen zu Taschen bleiben ein Nachfragebeleg.","hint":"Zähle zuerst die Fragen je Thema.","steps":"Vergleiche Licht mit der Summe der restlichen Fragen und bleibe bei den erfassten Anfragen.","example":"Wenn vier von zehn Anfragen Pumpen betreffen, ist das ein Bedarfssignal, auch wenn niemand gekauft hat.","id":31,"coreId":0,"reserveNo":2,"type":"multi","l":1,"c":0,"caseLabel":"LS 6.1 · Die Nachfrage an zwei Standorten vergleichen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M1"]},{"title":"Das erste Thema finden","scene":"In Leer wurden acht Fragen zu Familienausflügen, sieben zu Reparaturen und fünf zu Regenschutz festgehalten.","ask":"Welches Thema kam am häufigsten vor?","options":["Reparaturen unterwegs.","Regenschutz.","Sicheres Abstellen.","Zubehör für Familienausflüge.","Pendeln bei Dunkelheit.","Reparaturen und Regenschutz waren gemeinsam ein einzelnes Hauptanliegen."],"answer":[3],"why":"Acht ist die größte Anzahl unter den drei erfassten Themen.","hint":"Vergleiche die Zahlen für die drei einzelnen Themen.","steps":"Suche den größten Wert und lies seine Überschrift.","example":"Neun Fragen zu einem Thema bedeuten, dass es häufiger vorkam als ein Thema mit sechs Fragen.","id":32,"coreId":1,"reserveNo":1,"type":"multi","l":1,"c":0,"caseLabel":"LS 6.1 · Die Nachfrage an zwei Standorten vergleichen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M2"]},{"title":"Ein anderer Samstag","scene":"Übungsvariante: Leer zählt an einem anderen Samstag sechs Fragen zu Familienausflügen, acht zu Reparaturen unterwegs und vier zum Regenschutz.","ask":"Welche Hinweise passen zum Profil dieses Samstags?","options":["Familienausflüge wurden doppelt so oft wie Reparaturen genannt.","Reparaturen unterwegs waren das häufigste Thema.","Regenschutz fehlt in der Auswertung.","Acht Anfragen beweisen acht Käufe.","Auch für Familienausflüge bleibt ein Bedarf sichtbar.","Genau die Hälfte aller Fragen betraf Regenschutz."],"answer":[1,4],"why":"Reparaturen liegen mit acht Fragen vorne. Die sechs Fragen zu Ausflügen zeigen weiterhin einen Bedarf.","hint":"Vergleiche Häufigkeit und Bedeutung getrennt.","steps":"Ordne die drei Kategorien. Prüfe, welche danach weiterhin mit Fragen belegt sind.","example":"Auch das zweitgrößte Thema kann eine passende Warengruppe begründen.","id":33,"coreId":1,"reserveNo":2,"type":"multi","l":1,"c":0,"caseLabel":"LS 6.1 · Die Nachfrage an zwei Standorten vergleichen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M2"]},{"title":"Wer wählt die Ware?","scene":"In Leer suchen Kundinnen und Kunden auf der Aktionsfläche selbst aus. Fragen können sie an der Information stellen.","ask":"Woran erkennst du die Verkaufsform?","options":["Die Größe des Ladens legt die Verkaufsform fest.","Eine Person wird bei jedem Artikel von einer Fachkraft begleitet.","Die Kundschaft trifft die Auswahl zunächst selbst.","Die Information bleibt bei Rückfragen ansprechbar.","Die Auswahl findet nur an der Kasse statt.","Die Fläche muss bei Selbstbedienung ohne Schilder bleiben."],"answer":[2,3],"why":"Bei Selbstbedienung wählen Menschen selbst aus. Eine allgemeine Anlaufstelle für Rückfragen passt dazu.","hint":"Achte darauf, wer die Ware aussucht.","steps":"Trenne die erste Auswahl am Regal von einer späteren Rückfrage.","example":"Ein Kunde kann ein Produkt selbst aus dem Regal nehmen und bei Unsicherheit einen Mitarbeiter fragen.","id":34,"coreId":2,"reserveNo":1,"type":"multi","l":1,"c":0,"caseLabel":"LS 6.1 · Die Nachfrage an zwei Standorten vergleichen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M1","M2"]},{"title":"Zubehörtheke und Regal","scene":"Übungsvariante: In Geschäft A zeigt eine Verkäuferin an der Theke, welches Zubehör ans Rad passt. In Geschäft B finden Kundinnen passende Artikel anhand von Regalhinweisen; an einer Anlaufstelle können sie nachfragen.","ask":"Welche Aussagen geben den Unterschied richtig wieder?","options":["Beide Geschäfte nutzen ausschließlich persönliche Beratung.","Geschäft B braucht wegen der Anlaufstelle eine Begleitung an jedem Regal.","In A gehört persönliches Zeigen zur Auswahl.","Geschäft A hat eine größere Fläche als B.","Bei B ersetzt die Selbstbedienung jede Hilfe.","In B helfen Hinweise bei einer selbstständigen Auswahl."],"answer":[2,5],"why":"Die Beispiele zeigen verschiedene Wege der Auswahl. In A unterstützt die Verkäuferin am Produkt, in B ermöglichen Hinweise zunächst die selbstständige Wahl.","hint":"Unterscheide Hinweise am Regal und Begleitung am Produkt.","steps":"Beschreibe pro Laden, wer bei der Auswahl zuerst tätig wird.","example":"Eine verständliche Produktkennzeichnung kann einen ersten Vergleich ohne Gespräch ermöglichen.","id":35,"coreId":2,"reserveNo":2,"type":"multi","l":1,"c":0,"caseLabel":"LS 6.1 · Die Nachfrage an zwei Standorten vergleichen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M1","M2"]},{"title":"Kleine Dinge am Rad","scene":"Eine Anfrage bei Block lautet: „Wohin mit meinen Schlüsseln, wenn ich mit dem Rad fahre?“ Jede Anfrage soll genau einem Hauptanliegen zugeordnet werden.","ask":"Welche Kategorie passt am besten?","options":["Sicheres Abstellen.","Regenschutz für den Sattel.","Sichtbarkeit bei Dunkelheit.","Reparaturen unterwegs.","Transport kleiner Dinge.","Nutzung des Werkstattzugangs."],"answer":[4],"why":"Hier sucht jemand einen Platz für kleine Gegenstände unterwegs. Darum passt der Transport kleiner Dinge.","hint":"Schau auf das Problem, das der Kunde lösen will.","steps":"Lies den Satz ohne an ein bestimmtes Produkt zu denken. Wähle danach die passende Bedarfskategorie.","example":"Bei einer Frage nach Schutz vor Regen steht Regenschutz im Vordergrund.","id":36,"coreId":3,"reserveNo":1,"type":"multi","l":1,"c":3,"caseLabel":"LS 6.1 · Die Nachfrage an zwei Standorten vergleichen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M1","M6"]},{"title":"Hauptanliegen aus zwei Hinweisen","scene":"Übungsvariante: In einem Beratungsgespräch sagt jemand: „Ich fahre oft im Dunkeln, aber heute suche ich wirklich nur eine kleine Tasche für mein Portemonnaie.“ Pro Anfrage wird ein Hauptanliegen erfasst.","ask":"Welche Einträge sind fachlich sinnvoll?","options":["Zwei Zähleinträge für Dunkelheit und kleine Gegenstände.","Ein Zähleintrag für den Transport kleiner Dinge.","Ein Verkauf für Beleuchtung.","Ein Zähleintrag für sicheres Abstellen.","Eine Zusatznotiz zur Fahrt bei Dunkelheit ohne weitere Zählung.","Ein Eintrag unter Pannen unterwegs."],"answer":[1,4],"why":"Gefragt wurde nach einer Möglichkeit, das Portemonnaie zu transportieren. Der Hinweis auf Dunkelheit kann als Kontext stehen, ohne doppelt zu zählen.","hint":"Achte auf die Formulierung „heute suche ich“.","steps":"Trenne den Hintergrund vom aktuellen Hauptanliegen und zähle die Anfrage nur einmal.","example":"Erzählt eine Person von Regen, fragt aber gezielt nach einer Pumpe, zählt die konkrete Pumpenfrage.","id":37,"coreId":3,"reserveNo":2,"type":"multi","l":1,"c":3,"caseLabel":"LS 6.1 · Die Nachfrage an zwei Standorten vergleichen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M1","M6"]},{"title":"Den Tresen markieren","scene":"Auf Blocks Aktionsfläche steht ein fester Beratungstresen. Für den Aufbau gibt es außerdem zwei Rollregale und einen kleinen Tisch.","ask":"Wie gehst du beim Skizzieren damit um?","options":["Ich zeichne den festen Tresen an seinem ausgewiesenen Platz ein.","Ich entferne den Tresen aus der Skizze, wenn der Tisch sonst keinen Platz hat.","Ich kennzeichne die Rollregale als verschiebbare Ausstattung.","Ich setze den Hauptgang in der Skizze mit dem Tresen gleich.","Ich übernehme statt Rollregalen die Gondeln aus Leer.","Ich behandle den Tresen wie ein Regal auf Rollen."],"answer":[0,2],"why":"Ein fester Tresen bleibt eine Vorgabe des Standorts. Rollregale lassen sich im Modell verschieben und auf mögliche Positionen prüfen.","hint":"Was bleibt fest und was kann verschoben werden?","steps":"Ordne beide Arten von Möbeln getrennt in der Skizze ein.","example":"Ein fest eingebauter Kassentresen bleibt in der Zeichnung an seinem Platz.","id":38,"coreId":4,"reserveNo":1,"type":"multi","l":1,"c":0,"caseLabel":"LS 6.1 · Die Nachfrage an zwei Standorten vergleichen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M3","M6"]},{"title":"Gondel am Rand prüfen","scene":"Übungsvariante: Eine beidseitig bestückte Gondel in Leer steht in einer Skizze mit einer langen Seite direkt an der Wand. Der Kundenweg soll beide Warenseiten erreichen.","ask":"Welche Beurteilungen sind richtig?","options":["Die Gondel ist von beiden Seiten erreichbar, solange der Hauptgang frei bleibt.","Bei dieser Position fehlt der Zugang an einer Warenseite.","Die Aufstellung erhöht die Aktionsfläche.","Die Ware auf der Wandseite ist bei Selbstbedienung trotzdem gut erreichbar.","Die Gondel kann anders platziert werden, wenn Wege und Fläche das zulassen.","Die zweite Warenseite muss zwingend weiter bestückt bleiben, selbst wenn niemand herankommt."],"answer":[1,4],"why":"An der Wand ist die zweite Seite für die Kundschaft nicht erreichbar. Der Aufbau muss zur beidseitigen Nutzung passen.","hint":"Verfolge den Weg zu jeder der beiden langen Seiten.","steps":"Markiere am Modell die Wand und zeige, von wo man an die Ware kommt.","example":"Ein einseitiges Regal funktioniert an der Wand. Eine beidseitig belegte Gondel braucht Platz auf beiden Seiten.","id":39,"coreId":4,"reserveNo":2,"type":"multi","l":1,"c":0,"caseLabel":"LS 6.1 · Die Nachfrage an zwei Standorten vergleichen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M3","M6"]},{"title":"Länge auf dem Plan","scene":"Blocks Rollregal ist 1,00 m lang. Die Skizze verwendet 1:25.","ask":"Wie lang zeichnest du das Regal?","options":["25,0 cm.","2,5 cm.","1,0 cm.","40,0 cm.","4,0 cm.","0,4 cm."],"answer":[4],"why":"1,00 m sind 100 cm. 100 ÷ 25 = 4,0 cm im Plan.","hint":"Rechne erst Meter in Zentimeter um.","steps":"Teile die tatsächliche Länge in Zentimetern durch die Maßstabszahl.","example":"75 cm im Laden werden bei 1:25 zu 3 cm auf dem Blatt.","id":40,"coreId":5,"reserveNo":1,"type":"multi","l":1,"c":3,"caseLabel":"LS 6.1 · Die Nachfrage an zwei Standorten vergleichen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M3"]},{"title":"Vom Plan zurückrechnen","scene":"Übungsvariante: Du findest in einer Skizze im Maßstab 1:25 einen Weg, der 5,2 cm breit gezeichnet ist.","ask":"Welche Angaben zur tatsächlichen Breite stimmen?","options":["Der Weg ist 130 cm breit.","Der Weg ist 2,08 cm breit.","Der Weg ist 5,2 m breit.","Der Weg ist 1,30 m breit.","Der Weg ist 0,52 m breit.","Der Weg ist 25 cm breit."],"answer":[0,3],"why":"5,2 × 25 = 130 cm und 130 cm entsprechen 1,30 m.","hint":"Vom kleinen Plan zum Laden wird die Länge größer.","steps":"Multipliziere 5,2 cm mit 25 und rechne dann den Wert in Meter um.","example":"Bei 1:25 entsprechen 2 cm auf der Skizze 50 cm im Laden.","id":41,"coreId":5,"reserveNo":2,"type":"multi","l":1,"c":3,"caseLabel":"LS 6.1 · Die Nachfrage an zwei Standorten vergleichen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M3"]},{"title":"Freien Zugang vorziehen","scene":"Dein Lieblingsplatz für das Schild bei Block liegt im Werkstattzugang. Laut Plan muss der Zugang frei bleiben.","ask":"Was machst du zuerst?","options":["Ich streiche den Standort im Zugang aus meinem Vorschlag.","Ich lasse das Schild zunächst im Zugang stehen.","Ich frage erst nach der Schriftfarbe.","Ich lasse die Kundschaft selbst beurteilen, ob sie vorbei kann.","Ich ersetze den Zugang in der Skizze durch einen kürzeren Weg, ohne den Laden zu fragen.","Ich verlasse mich auf die schmale Bauform des Schilds."],"answer":[0],"why":"Die Vorgabe hat Vorrang. Wenn die geplante Stelle im freien Zugang liegt, braucht das Schild einen anderen Platz.","hint":"Ist der freie Zugang eine Wahlmöglichkeit?","steps":"Nenne die Vorgabe und prüfe deinen bevorzugten Standort daran.","example":"Eine Sonderfläche kann umgestaltet werden, ein ausdrücklich freizuhaltender Gang bleibt frei.","id":42,"coreId":6,"reserveNo":1,"type":"multi","l":1,"c":1,"caseLabel":"LS 6.1 · Die Nachfrage an zwei Standorten vergleichen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M3","M5","M6"]},{"title":"Den zweiten Entwurf prüfen","scene":"Übungsvariante: Du wolltest bei Leer ein großes Schild neben der Gondel. Beim Probeaufbau nimmt der Fuß genau den Platz ein, den man zum Erreichen einer Warenseite braucht.","ask":"Welche Reaktionen zeigen, dass du deine erste Idee prüfst?","options":["Ich lasse das Schild, weil es gut sichtbar ist.","Ich übernehme die wichtigen Angaben direkt am Regal, wenn dort genug Platz ist.","Ich drehe die Zeichnung, ohne den Aufbau zu ändern.","Ich teste einen neuen Standort, an dem beide Warenseiten nutzbar bleiben.","Ich streiche den Hinweis auf die schwer erreichbare Seite aus dem Testprotokoll.","Ich stelle das Schild vor die Ware, obwohl man dann nicht mehr an sie herankommt."],"answer":[1,3],"why":"Der Zugang zu beiden Warenseiten muss funktionieren. Durch einen anderen Schildplatz oder eine Regalinfo bleiben Ziel und Zugang erhalten.","hint":"Was sollte das Schild erreichen, und wo liegt das Problem?","steps":"Trenne den Informationsbedarf von deinem ersten Aufbau. Suche eine passende Lösung für beides.","example":"Ein versetzter Hinweis kann dieselbe Orientierung bieten wie ein großes Schild am ursprünglichen Platz.","id":43,"coreId":6,"reserveNo":2,"type":"multi","l":1,"c":1,"caseLabel":"LS 6.1 · Die Nachfrage an zwei Standorten vergleichen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M3","M5","M6"]},{"title":"Eine gemeinsame Idee prüfen","scene":"Sarah möchte Zeit sparen, indem beide Läden dieselbe Gestaltung erhalten. Sebastian sagt, die Flächen unterscheiden sich.","ask":"Welche Prüfung ist sinnvoll?","options":["Wir entscheiden nur nach dem Zeitgewinn.","Wir klären, welche Gestaltungselemente auf beiden Flächen funktionieren.","Wir erklären jedes gemeinsame Element für ungeeignet.","Wir planen zuerst den großen Entwurf und prüfen nur Leer.","Wir vergleichen Fläche und Verkaufsform für beide Läden.","Wir nehmen an, dass dieselbe Warenzahl denselben Aufbau erlaubt."],"answer":[1,4],"why":"Die gemeinsame Idee kann nützlich sein. Der Vergleich zeigt, welche Elemente übertragbar sind und welche angepasst werden müssen.","hint":"Zerlege die Idee in konkrete Teile.","steps":"Prüfe etwa ein Schild und einen Tisch jeweils anhand der Bedingungen in beiden Läden.","example":"Ein gemeinsames Aktionsmotiv braucht in zwei Läden nicht denselben Schildhalter.","id":44,"coreId":7,"reserveNo":1,"type":"multi","l":1,"c":1,"caseLabel":"LS 6.1 · Die Nachfrage an zwei Standorten vergleichen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["Handlungssituation","M5"]},{"title":"Schneller Aufbau, andere Bedingungen","scene":"Übungsvariante: Du hast einen zentralen Aktionstisch für beide Standorte vorgeschlagen. Der Platzplan zeigt am kleinen Standort einen festen Tresen, am größeren stehen schon Gondeln.","ask":"Welche Schritte helfen dir beim Überarbeiten?","options":["Den Aktionstisch beibehalten und vorhandene Möbel im Plan ausblenden.","Beide Originalskizzen ohne erneute Prüfung austauschen.","Prüfen, was der Tisch leisten sollte und welche vorhandenen Möbel das übernehmen können.","Das größere Geschäft allein über beide Flächen entscheiden lassen.","Die veränderte Empfehlung mit konkreten Angaben zu beiden Flächen begründen.","Den Zeitgewinn als Nachweis für die Passung des Aufbaus verwenden."],"answer":[2,4],"why":"Die vorhandene Ausstattung ist Teil der Bedingungen. Die Idee lässt sich prüfen, ohne ihren Zweck aufzugeben.","hint":"Wozu sollte der Tisch dienen?","steps":"Formuliere zuerst das Ziel deiner Idee. Prüfe pro Standort andere Wege zum selben Ziel.","example":"Produkte können an einer Gondel präsent sein, wenn für einen zusätzlichen Tisch kein Platz vorhanden ist.","id":45,"coreId":7,"reserveNo":2,"type":"multi","l":1,"c":1,"caseLabel":"LS 6.1 · Die Nachfrage an zwei Standorten vergleichen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["Handlungssituation","M5"]},{"title":"Nach dem Grund fragen","scene":"Jemand aus eurem Team möchte das Pannenzubehör in Leer nahe der Information platzieren. Eine zweite Person bevorzugt den Eingang der Aktionsfläche.","ask":"Welche erste Rückfrage bringt den Vergleich weiter?","options":["Wer hat seinen Vorschlag zuerst gemacht?","Wer braucht weniger Zeit für seine Skizze?","Wo und warum erwartet ihr, dass die Kundschaft zuerst nach Pannenzubehör sucht?","Können wir die zwei Vorschläge ohne Prüfung nebeneinander lassen?","Wessen Skizze sieht ordentlicher aus?","Können wir den Hauptgang unabhängig vom Vergleich belegen?"],"answer":[2],"why":"Eine Frage nach dem Suchweg macht den Nutzen der beiden Positionen besprechbar.","hint":"Welches gemeinsame Ziel sollen beide Positionen erreichen?","steps":"Formuliere eine Frage, die beide Personen anhand der Fallangaben beantworten können.","example":"Eine Rückfrage zum Kundenweg hilft mehr als eine Frage nach dem Lieblingsregal.","id":46,"coreId":8,"reserveNo":1,"type":"multi","l":1,"c":2,"caseLabel":"LS 6.1 · Die Nachfrage an zwei Standorten vergleichen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M2","M3","M4"]},{"title":"Zwei Ideen ausprobieren","scene":"Übungsvariante: In Leer sollen Familien auf einen Blick passendes Reparaturzubehör finden. Ein Teammitglied will nach Artikeln sortieren, ein anderes nach Pannenproblem.","ask":"Welche Beiträge fördern eine fachliche Einigung?","options":["Eine Idee streichen, bevor ihre Begründung bekannt ist.","Beide Personen erklären lassen, wie Familien mit ihrer Ordnung suchen.","Die schönere Darstellung ohne Test auswählen.","Eine typische Kundenfrage in beiden Entwürfen nacheinander durchspielen.","Nur die Namen der Beteiligten festhalten.","Per Abstimmung entscheiden, welche Ordnung in beiden Entwürfen aufgebaut wurde."],"answer":[1,3],"why":"Die Gruppe vergleicht die Ideen anhand desselben Kundenziels. Eine Testfrage zeigt, bei welcher Ordnung der Weg zur Ware verständlicher ist.","hint":"Vergleiche mit derselben Suchaufgabe.","steps":"Gib beiden Vorschlägen Platz. Prüfe danach an einem Fall aus Leer, wie schnell die Kundschaft zum passenden Artikel gelangt.","example":"„Wo finde ich etwas für einen platten Reifen?“ lässt sich in beiden Entwürfen als Testfrage verwenden.","id":47,"coreId":8,"reserveNo":2,"type":"multi","l":1,"c":2,"caseLabel":"LS 6.1 · Die Nachfrage an zwei Standorten vergleichen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M2","M3","M4"]},{"title":"Mit gleichen Kriterien helfen","scene":"Im Team beschreibt eine Person nur Blocks Kundschaft. Eine andere beschreibt nur die Fläche in Leer. Jan soll beide Läden vergleichen.","ask":"Welche Ergänzung hilft zuerst?","options":["Jeweils alle Hinweise zum anderen Laden streichen.","Eine Gesamtzahl für beide Standorte nennen.","Für beide Läden dieselben Punkte erheben, etwa Nachfrage, Verkaufsform und Fläche.","Blocks Nachfrage mit Leers Fläche verrechnen.","Einen Standort als alleinige Vorlage wählen.","Die Ladenprofile nach Textlänge sortieren."],"answer":[2],"why":"Ein Standortvergleich braucht Informationen zu denselben Kriterien. Sonst stehen bloß zwei verschiedene Beschreibungen nebeneinander.","hint":"Wo steht pro Kriterium die Angabe zum zweiten Laden?","steps":"Zeichne zwei Standortspalten und dieselben Kriterien als Zeilen. Ergänze die leeren Felder.","example":"Zwei Wegbreiten lassen sich vergleichen. Eine Wegbreite und die Zahl der Kundenanfragen beantworten verschiedene Fragen.","id":48,"coreId":9,"reserveNo":1,"type":"multi","l":1,"c":2,"caseLabel":"LS 6.1 · Die Nachfrage an zwei Standorten vergleichen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["Handlungssituation","M5"]},{"title":"Den wichtigsten Unterschied auswählen","scene":"Übungsvariante: Für den Termin nennt eine Person die größere Fläche in Leer als wichtigsten Unterschied, eine andere die Art der Beratung.","ask":"Welche Absprachen dienen Jans Entscheidung?","options":["Wir nehmen den Unterschied mit der größten Zahl, ohne seine Folgen zu prüfen.","Wir nennen beide Unterschiede ohne Rangfolge, obwohl Jan einen Schwerpunkt verlangt.","Wir erklären für beide Vorschläge, was sie an jedem Aufbau ändern.","Wir empfehlen den Unterschied, den die Gruppe zuerst gefunden hat.","Wir entscheiden, welche Folge für diese Aktion stärker ins Gewicht fällt.","Wir diskutieren nur, welche Aussage leichter vorzulesen ist."],"answer":[2,4],"why":"Mehrere Unterschiede sind relevant. Der Vergleich ihrer Folgen zeigt, welchen das Team als wichtigsten bezeichnen kann.","hint":"Frage bei jedem Vorschlag: Welche Entscheidung ändert sich dadurch?","steps":"Stütze beide Vorschläge mit Angaben zum Fall und vergleiche ihre Folgen für Aurich und Leer.","example":"Die Verkaufsform kann entscheidender sein als die reine Fläche, wenn sie bestimmt, wie Kundinnen passendes Zubehör finden.","id":49,"coreId":9,"reserveNo":2,"type":"multi","l":1,"c":2,"caseLabel":"LS 6.1 · Die Nachfrage an zwei Standorten vergleichen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["Handlungssituation","M5"]},{"title":"Den richtigen Materialtyp wählen","scene":"Für Block brauchst du das Maß des kleinen Tischs. Zur Auswahl stehen Kurzprofil, Planungsunterlage und Nachfrageauswertung.","ask":"Welche Stelle hilft dir?","options":["Die Zahl der 20 erfassten Anfragen in M1.","Eine Kundenäußerung über Schlösser in M1.","Die Angaben zu Warenträgern in M3.","Die Definition von Zielgruppe in M6.","Das Feld für Prioritäten in M5.","Die Nachfrage nach Reparaturen in M2."],"answer":[2],"why":"Die Größe des Tischs steht bei Flächen und Warenträgern, nicht in den Kundenangaben.","hint":"Suchst du eine Meinung oder ein Maß?","steps":"Suche die Unterlage, die Möbel und Maße erfasst.","example":"Für die Breite eines Tisches ist eine Ausstattungsliste hilfreicher als die Zahl der Anfragen.","id":50,"coreId":10,"reserveNo":1,"type":"multi","l":1,"c":4,"caseLabel":"LS 6.1 · Die Nachfrage an zwei Standorten vergleichen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M1","M2","M3","M4"]},{"title":"Zwei Behauptungen prüfen","scene":"Ein Team schreibt: „In Leer gibt es zwei Gondeln. Kundinnen fragen dort nach Zubehör für Pannen unterwegs.“","ask":"Welche Quellenpaare passen zu den beiden Behauptungen?","options":["M1 für Gondeln und M5 für die Pannenfrage.","M2 für Gondeln und nur M3 für die Kundenfrage.","M3 für Gondeln und M2 für die Kundenfrage.","M6 für die Anzahl der Gondeln und M1 für Pannen in Leer.","M3 für Gondeln und M4 für die Kundenfrage.","M5 für beide, obgleich es eine leere Vorlage ist."],"answer":[2,4],"why":"M3 nennt die Ausstattung. Die konkrete Nachfrage in Leer lässt sich aus dem Kurzprofil oder dem dortigen Sprechtext belegen.","hint":"Weise jeder Behauptung ihren passenden Quellentyp zu.","steps":"Unterstreiche erst das Möbel, dann die Kundenfrage. Suche für beide Aussagen eine konkrete Fundstelle.","example":"Eine Regalanzahl gehört in den Flächenplan, eine Kundenfrage in ein Profil oder einen Gesprächsvermerk.","id":51,"coreId":10,"reserveNo":2,"type":"multi","l":1,"c":4,"caseLabel":"LS 6.1 · Die Nachfrage an zwei Standorten vergleichen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M1","M2","M3","M4"]},{"title":"Die Kundenaussage erfassen","scene":"Bei Block fragt eine Person: „Könnte ich sehen, wie man das Licht am Lenker befestigt?“","ask":"Welche kurze Notiz gibt die Aussage wieder?","options":["Lichtset am Lenker montiert und verkauft.","Kundin verlangt ein neues Fahrrad.","Befestigung geht bei jedem Licht nur am Lenker.","Die Person möchte sehen, wie das Licht am Lenker befestigt wird.","Kundin beschwert sich über zu wenig Licht.","Fahrrad brachte bereits ein kaputtes Licht mit."],"answer":[3],"why":"Die Frage belegt den Wunsch nach einer Vorführung. Über Kauf, alte Beleuchtung oder allgemeine Montagevorgaben steht dort nichts.","hint":"Gib den geäußerten Wunsch in eigenen Worten wieder.","steps":"Entferne alle Informationen, die du nur vermutest.","example":"Aus „Kann ich das ausprobieren?“ wird „möchte testen“, nicht „hat gekauft“.","id":52,"coreId":11,"reserveNo":1,"type":"multi","l":1,"c":4,"caseLabel":"LS 6.1 · Die Nachfrage an zwei Standorten vergleichen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M1","M2"]},{"title":"Kundenstimmen trennen","scene":"Übungsvariante: Bei Block fragt jemand nach der Montage einer Tasche am eigenen Rahmen. In Leer fragt eine andere Person, wo Taschen für Schlüssel liegen.","ask":"Welche Einträge halten beide Anliegen passend fest?","options":["Block: Wunsch nach Erklärung der Montage am Rahmen.","Block: Alle Taschen passen an jeden Rahmen.","Leer: Tasche schon gekauft.","Beide: Die Kundschaft lehnt persönliche Beratung grundsätzlich ab.","Leer: Zubehör für Schlüssel soll im Laden auffindbar sein.","Block: Die Person sucht eine Erklärung für Pannenreparaturen."],"answer":[0,4],"why":"Beide Anfragen betreffen Taschen. In Aurich geht es um Montage, in Leer um das Auffinden der passenden Ware.","hint":"Gleiche Produktgruppe, verschiedene Fragen.","steps":"Notiere für jeden Standort das gesuchte Ergebnis in einem Satz.","example":"Wer nach dem Ort eines Artikels fragt, braucht zunächst eine Weg- oder Regalinfo.","id":53,"coreId":11,"reserveNo":2,"type":"multi","l":1,"c":4,"caseLabel":"LS 6.1 · Die Nachfrage an zwei Standorten vergleichen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M1","M2"]},{"title":"Platz für die Vorführung","scene":"Bei Block möchte ein Kunde ausprobieren, ob ein Schloss an sein Fahrrad passt. Der Werkstattzugang muss frei bleiben.","ask":"Welche Lösung erfüllt beides?","options":["Schloss am Fahrrad im Werkstattzugang testen.","Fahrrad zum Prüfen vor den Hauptgang stellen.","Den Test ohne Blick aufs Fahrrad durch ein allgemeines Preisetikett ersetzen.","Das Fahrrad am vorgesehenen Beratungsplatz abstellen und den Zugang freihalten.","Die Montagefrage an die Aktionsfläche in Leer verweisen.","Die Fachkraft vor dem Zugang beraten lassen, solange niemand vorbeiwill."],"answer":[3],"why":"Bei Block kann am Fahrrad beraten werden, wenn es dafür außerhalb der freien Wege Platz hat.","hint":"Beratung und Weg müssen gleichzeitig funktionieren.","steps":"Prüfe bei jeder Lösung den Standort des Fahrrads und den Verkehr zur Werkstatt.","example":"Bei einer Vorführung genügt ein kleiner Platz, sofern Fahrrad und Beratung komplett dort bleiben.","id":54,"coreId":12,"reserveNo":1,"type":"multi","l":2,"c":0,"caseLabel":"LS 6.1 · Die Nachfrage an zwei Standorten vergleichen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M1","M3"]},{"title":"Beratung im Betrieb erproben","scene":"Übungsvariante: Block erprobt zwei Positionen für die persönliche Beratung. Bei A steht das Rad beim Test teilweise im Gang. Bei B bleibt der Gang frei; die Fachkraft erreicht Licht und Schloss mit einem Schritt.","ask":"Welche Schlüsse sind sinnvoll?","options":["A ist allein wegen der Nähe zum Zugang zu bevorzugen.","B wahrt beim Test den freien Gang.","In A reicht es, wenn die Gangbreite ohne Fahrrad eingehalten wird.","Beim weiteren Test soll auch genug Bewegungsraum am Fahrrad geprüft werden.","B ist nur geeignet, wenn Ratsuchende das Licht ohne Fachkraft montieren.","Durch die Auswahl von B muss der Werkstattzugang nicht mehr überprüft werden."],"answer":[1,3],"why":"Die Funktion beim tatsächlichen Benutzen zählt. B wahrt den Gang; Bewegungsraum und freie Zugänge sind weitere Prüfpunkte.","hint":"Beurteile den Aufbau mit Fahrrad und Beratung, nicht nur die leere Fläche.","steps":"Verfolge im Modell den Weg eines vorbeigehenden Menschen und den Bewegungsraum der beratenden Person.","example":"Ein Tisch kann im leeren Plan gut stehen und dennoch beim Ausprobieren einen Engpass erzeugen.","id":55,"coreId":12,"reserveNo":2,"type":"multi","l":2,"c":0,"caseLabel":"LS 6.1 · Die Nachfrage an zwei Standorten vergleichen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M1","M3"]},{"title":"Eine klare Regalinfo","scene":"In Leer fragen Familien nach Ausrüstung für eine Panne. Auf der Aktionsfläche wählen sie selbst aus.","ask":"Welche Lösungen helfen ihnen direkt?","options":["Pannenzubehör zusammenstellen und verständlich kennzeichnen.","Das Zubehör hinter einem unbesetzten Beratungstresen aufbewahren.","Alle Waren nur nach Liefernummern sortieren und keine Orientierung geben.","Ein Schild weist vom Eingang zum Pannenbereich.","Das Pannenzubehör ohne Hinweis auf beide Gondeln verteilen.","Die Beschriftung erst nach dem Samstag anbringen."],"answer":[0,3],"why":"Wer selbst auswählt, braucht einen verständlichen Weg und erkennbare Warengruppen. Dafür ist niemand dauerhaft am Regal nötig.","hint":"Wo beginnt die Suche?","steps":"Prüfe, wie Familien den Bereich finden und die Produkte voneinander unterscheiden.","example":"„Reparatur unterwegs“ ist als Regalhinweis aus Kundensicht besser auffindbar als eine Warennummer.","id":56,"coreId":13,"reserveNo":1,"type":"multi","l":2,"c":0,"caseLabel":"LS 6.1 · Die Nachfrage an zwei Standorten vergleichen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M2","M4"]},{"title":"Selbstvergleich bei Regenschutz","scene":"Übungsvariante: In Leer sollen zwei Arten von Regenschutz für Fahrräder verkauft werden. Auf der Fläche ist samstags niemand fest zur Beratung eingeplant. Kundinnen sollen erkennen, wofür die Varianten gedacht sind.","ask":"Welche Gestaltung hilft?","options":["Ein Schild verspricht, jede Variante passe in jedem Fall.","Ein kleines Vergleichsschild nennt, was jede Variante schützt.","Die Varianten liegen ohne Namen in einem Karton.","Das Angebot heißt nur „Jetzt günstig“, ohne die Unterschiede zu nennen.","Am Regal steht, wo bei Unsicherheit eine Rückfrage möglich ist.","Die Varianten können ausschließlich nach Freigabe durch eine Fachkraft angesehen werden."],"answer":[1,4],"why":"Eine klare Vergleichsinformation unterstützt die Selbstbedienung. Die erreichbare Information ergänzt sie bei Fragen.","hint":"Welche Unterschiede müssen Kundinnen auf der Fläche selbst erkennen?","steps":"Prüfe Beschriftung und Rückfrageweg. Versprich keine ungeprüfte Passung.","example":"Hinweise wie „für den Sattel“ und „für den Gepäckträger“ helfen, Varianten voneinander zu unterscheiden.","id":57,"coreId":13,"reserveNo":2,"type":"multi","l":2,"c":0,"caseLabel":"LS 6.1 · Die Nachfrage an zwei Standorten vergleichen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M2","M4"]},{"title":"Die Waren auswählen","scene":"In Blocks Matrix steht „Zubehör zur besseren Sichtbarkeit anbieten“. Daneben steht „Schild zur Lichtmontage am Regal anbringen“.","ask":"Welche Aussagen ordnen die Vorschläge richtig zu?","options":["Das Auswahlziel für Sichtbarkeit ist eine Angabe zum Ladenweg.","Das Angebot von Sichtbarkeitszubehör betrifft das Sortiment.","Die Auswahl des Produkttyps ist nur eine Frage der Beschriftung.","Das Schild betrifft die Präsentation.","Beide Vorschläge beschreiben ausschließlich Preise.","Das Regalschild ist selbst ein Artikel des Aktionssortiments."],"answer":[1,3],"why":"Das Sortiment legt fest, was angeboten wird. Die Präsentation legt fest, wie die Produkte erkennbar gezeigt werden.","hint":"Achte auf die Tätigkeiten „anbieten“ und „kennzeichnen“.","steps":"Formuliere für jeden Vorschlag die Frage, die er beantwortet: „Welche Ware?“ oder „Wie gezeigt?“","example":"Eine Liste mit Schlössern betrifft das Sortiment; eine gut erreichbare Schlosswand betrifft die Präsentation.","id":58,"coreId":14,"reserveNo":1,"type":"multi","l":2,"c":0,"caseLabel":"LS 6.1 · Die Nachfrage an zwei Standorten vergleichen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M5"]},{"title":"Eine gemischte Aussage teilen","scene":"Übungsvariante: Euer Entwurf lautet: „Für Leer Pumpen und Werkzeug wählen, die Ware unter ‚Pannenhilfe‘ gemeinsam ausstellen und die Pumpen nach Ventilarten beschriften.“","ask":"Welche Teile gehören im Ergebnisblatt zur Präsentation?","options":["Pumpen ins Angebot aufnehmen.","Werkzeug auswählen.","Die ausgewählte Ware als Gruppe unter „Pannenhilfe“ ausstellen.","Die Nachfrage nach Reparaturen erheben.","Die Produkte zur Auswahl nach ihrer Lieferbarkeit prüfen.","Ventilarten am Regal kenntlich machen."],"answer":[2,5],"why":"Das Ausstellen und Beschriften betrifft, wie die Ware gezeigt wird. Die Entscheidung für Pumpen und Werkzeug ist die Warenauswahl.","hint":"Teile den Entwurf in einzelne Handlungen.","steps":"Prüfe bei jeder Handlung, ob sie Ware auswählt oder die gewählte Ware für Kundinnen sichtbar macht.","example":"„Minipumpe anbieten“ und „nach Ventiltypen ordnen“ gehören in verschiedene Felder.","id":59,"coreId":14,"reserveNo":2,"type":"multi","l":2,"c":0,"caseLabel":"LS 6.1 · Die Nachfrage an zwei Standorten vergleichen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M5"]},{"title":"Rollregal maßstäblich einzeichnen","scene":"Das Rollregal bei Block misst 1,00 m × 0,40 m. Du zeichnest bei 1:25.","ask":"Welche Zeichnung stimmt?","options":["10,0 cm × 4,0 cm.","4,0 cm × 1,6 cm.","2,5 cm × 1,0 cm.","4,0 cm × 0,4 cm.","40,0 cm × 16,0 cm.","100,0 cm × 40,0 cm."],"answer":[1],"why":"100 ÷ 25 = 4 und 40 ÷ 25 = 1,6. Beide Seitenlängen werden im selben Maßstab verkleinert.","hint":"Rechne beide Längen in Zentimeter um.","steps":"Teile jede der beiden Längen durch 25.","example":"Ein 50 cm tiefer Tisch ist bei 1:25 im Plan 2 cm tief.","id":60,"coreId":15,"reserveNo":1,"type":"multi","l":2,"c":3,"caseLabel":"LS 6.1 · Die Nachfrage an zwei Standorten vergleichen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M3"]},{"title":"Zwei Möbel in einer Skizze","scene":"Übungsvariante: Für Leer willst du eine neue Ausstellung in 1:25 skizzieren. Ein Tisch misst 1,20 m × 0,75 m und ein kleines Regal 1,50 m × 0,50 m.","ask":"Welche Maße gehören auf die Zeichnung?","options":["Tisch: 12,0 cm × 7,5 cm.","Regal: 5,0 cm × 1,5 cm.","Tisch: 4,8 cm × 0,75 cm.","Tisch: 4,8 cm × 3,0 cm.","Regal: 6,0 cm × 2,0 cm.","Regal: 15,0 cm × 5,0 cm."],"answer":[3,4],"why":"Der Tisch ergibt 120 ÷ 25 und 75 ÷ 25. Beim Regal rechnest du 150 ÷ 25 und 50 ÷ 25.","hint":"Nutze für beide Möbel dieselbe Maßstabszahl.","steps":"Schreibe alle vier echten Längen in Zentimetern auf und rechne sie einzeln um.","example":"1,25 m geteilt durch 25 ergeben 5 cm in der Skizze.","id":61,"coreId":15,"reserveNo":2,"type":"multi","l":2,"c":3,"caseLabel":"LS 6.1 · Die Nachfrage an zwei Standorten vergleichen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M3"]},{"title":"Rechteckfläche bestimmen","scene":"Blocks Aktionsfläche ist 3,60 m breit und 3,20 m tief. In diesem Rechteck steht der feste Tresen.","ask":"Welche Aussagen helfen beim Flächenvergleich?","options":["Blocks Rechteck misst 6,80 m².","Das Rechteck misst 11,52 m².","Die Skizze darf den Tresen als zusätzliche Fläche hinzurechnen.","Die Breite allein gibt die Fläche an.","Für bewegliche Möbel steht wegen des festen Tresens weniger freie Fläche zur Verfügung.","Der Hauptgang darf deshalb als Stellfläche eingeplant werden."],"answer":[1,4],"why":"3,60 × 3,20 ergeben 11,52 m². Der Tresen und freie Wege begrenzen, wo Möbel stehen können.","hint":"Rechne Länge mal Breite.","steps":"Unterscheide die Größe des Rechtecks von dem Platz, auf den ein Möbel gestellt werden kann.","example":"Zwei Räume können dieselbe Größe haben, aber wegen einer festen Theke andere nutzbare Ecken bieten.","id":62,"coreId":16,"reserveNo":1,"type":"multi","l":2,"c":3,"caseLabel":"LS 6.1 · Die Nachfrage an zwei Standorten vergleichen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M3"]},{"title":"Gleiche Fläche, andere Möglichkeiten","scene":"Übungsvariante: Zwei Geschäfte haben jeweils ein Aktionsrechteck mit 12 m². A hat darin einen festen Tresen. B hat keinen Tresen, benötigt aber zwei erreichbare Seiten an der Gondel.","ask":"Welche Aussagen stimmen im Vergleich?","options":["Beide Läden können zwingend denselben Aufbau stellen.","Die rechteckige Aktionsfläche ist in beiden Geschäften gleich groß.","A hat mehr freie Stellfläche, weil es einen festen Tresen gibt.","B kann die Gondel ohne Prüfung direkt an die Wand rücken.","Die möglichen Aufbauten können sich durch Tresen und Zugänge unterscheiden.","Zugänge spielen für eine Fläche mit 12 m² keine Rolle."],"answer":[1,4],"why":"Die Maßzahl ist gleich. Feste Möbel und benötigte Zugänge können unterschiedliche Positionen sinnvoll oder möglich machen.","hint":"Ist gleiche Größe dasselbe wie gleiche Nutzung?","steps":"Markiere die festen und freizuhaltenden Bereiche in beiden Skizzen. Vergleiche danach mögliche Stellflächen.","example":"Ein Gang braucht auch dann Platz, wenn er in der Flächenberechnung kein eigenständiges Möbel ist.","id":63,"coreId":16,"reserveNo":2,"type":"multi","l":2,"c":3,"caseLabel":"LS 6.1 · Die Nachfrage an zwei Standorten vergleichen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M3"]},{"title":"Vorsichtig formulieren","scene":"Bei Block steht zu einer Auswertung: „Fünf von 20 Kundenanfragen betrafen den Transport kleiner Dinge.“","ask":"Welche Formulierung vermeidet eine Überdeutung?","options":["Alle anderen Kunden wollen keine Taschen.","Für fünf Aufbewahrungsartikel sind Käufe sicher.","In fünf der 20 erfassten Anfragen ging es um kleine Dinge unterwegs.","Jede vierte Person in der Stadt nutzt eine Rahmentasche.","Transport ist der wichtigste Wunsch bei Block.","Die Zahl gilt für alle künftigen Wochen."],"answer":[2],"why":"Die Formulierung bleibt bei Ort, Zeitraum der Erfassung und gezähltem Anliegen. Sie behauptet weder Käufe noch eine allgemeine Vorliebe.","hint":"Bleibe bei den erfassten Anfragen.","steps":"Streiche Verallgemeinerungen über Bevölkerung, Verkäufe oder Zukunft.","example":"Aus drei Anfragen wird „drei erfasste Fragen“, nicht „drei verkaufte Produkte“.","id":64,"coreId":17,"reserveNo":1,"type":"multi","l":2,"c":1,"caseLabel":"LS 6.1 · Die Nachfrage an zwei Standorten vergleichen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M1"]},{"title":"Begrenzten Zeitraum offenlegen","scene":"Übungsvariante: An einem nassen Samstag geht es in Leer bei der Hälfte von zwölf erfassten Anfragen um Regenschutz. Ein Teammitglied schreibt daraus: „Regenschutz wird in Leer das ganze Jahr am besten verkauft.“","ask":"Welche Korrekturen sind tragfähig?","options":["Nenne zwölf Verkäufe statt zwölf Anfragen.","Nenne sechs von zwölf erfassten Anfragen an diesem Samstag.","Übernimm die Behauptung, wenn sie gut zum geplanten Aufbau passt.","Kennzeichne den nassen Samstag als Kontext der Beobachtung.","Nenne Regenschutz als garantiert wichtigste Warengruppe im Jahresverlauf.","Streiche die beobachteten Anfragen, weil sie nicht alle Kundinnen und Kunden abbilden."],"answer":[1,3],"why":"Sechs Anfragen an einem nassen Tag sind ein Hinweis. Sie belegen weder den Jahresverlauf noch Verkäufe.","hint":"Welche Reichweite hat eine Auswertung von nur einem Tag?","steps":"Notiere Zahl, Tag und das besondere Wetter. Ziehe nur einen Schluss für die beobachtete Lage.","example":"Ein Sommerfest kann mehr Nachfrage nach Trinkflaschen bringen, ohne dass es in jeder Woche so ist.","id":65,"coreId":17,"reserveNo":2,"type":"multi","l":2,"c":1,"caseLabel":"LS 6.1 · Die Nachfrage an zwei Standorten vergleichen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M1"]},{"title":"Gänge vor Gestaltung","scene":"Ein Entwurf für Block macht den freien Hauptgang freiwillig, die gewünschte Farbe am Zusatzschild dagegen zur Pflicht.","ask":"Was korrigierst du?","options":["Ich behalte die Reihenfolge, weil die Farbe das Motiv trägt.","Ich markiere den freien Hauptgang als zwingend.","Ich kennzeichne die Farbe als Gestaltungsentscheidung, solange keine feste Vorgabe dafür besteht.","Ich mache ein großes Schild zur einzigen Möglichkeit der Beschriftung.","Ich streiche den Hauptgang aus der Prüfung, wenn die Verkaufsfläche klein ist.","Ich markiere den Gang nur für Tage mit vielen Anfragen als zwingend."],"answer":[1,2],"why":"Der Hauptgang muss laut Flächenangaben frei sein. Für eine bevorzugte Schildfarbe nennt der Fall keine gleichrangige Pflicht.","hint":"Frage, welche Regel ausdrücklich im Fall steht.","steps":"Unterscheide den vorgeschriebenen Zustand des Wegs von der gewünschten Ausgestaltung des Schilds.","example":"Ein freier Ausgang ist eine feste Bedingung; ein grünes Hinweisschild kann eine Gestaltungsidee sein.","id":66,"coreId":18,"reserveNo":1,"type":"multi","l":2,"c":1,"caseLabel":"LS 6.1 · Die Nachfrage an zwei Standorten vergleichen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M3","M4","M5"]},{"title":"Einen Zielkonflikt lösen","scene":"Übungsvariante: Du willst in Leer einen freistehenden Aufsteller verwenden. Bei der Prüfung zeigt sich, dass er eine Gondelseite verdeckt. Der Text könnte gleich gut direkt am Regal stehen.","ask":"Welche Prioritäten gehören in den neuen Entwurf?","options":["Zugang als wünschenswert eintragen, wenn der Aufsteller schöner wirkt.","Zugang zu beiden belegten Gondelseiten sichern.","Die Rückseite weiter befüllen, ohne Zugang einzuplanen.","Den Aufsteller als austauschbare Möglichkeit behandeln.","Regalbeschriftung als umsetzbare Alternative überprüfen.","Die geforderte Erreichbarkeit ohne Begründung aus dem Entwurf löschen."],"answer":[1,3,4],"why":"Kunden müssen beide Seiten der Gondel erreichen. Die Information kann an einem anderen Ort stehen, wenn sie weiterhin lesbar und verständlich ist.","hint":"Wofür ist der Aufsteller gedacht?","steps":"Plane zuerst den freien Kundenzugang. Wähle anschließend eine passende Art der Beschriftung.","example":"Ein Produkt kann dieselbe Erklärung über ein Regalschild erhalten, ohne einen Zugang mit einem Ständer zu belegen.","id":67,"coreId":18,"reserveNo":2,"type":"multi","l":2,"c":1,"caseLabel":"LS 6.1 · Die Nachfrage an zwei Standorten vergleichen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M3","M4","M5"]},{"title":"Aus Lob eine Hilfe machen","scene":"Eine Gruppe schreibt: „Die Skizze für Aurich wirkt gelungen.“ Ihr sollt ihr eine hilfreiche Rückmeldung zum Werkstattzugang geben.","ask":"Welche Rückfrage ist konkret und prüfbar?","options":["Kannst du alle Farben intensiver machen?","Können wir die Skizze genauso übernehmen?","Warum habt ihr nicht überall dieselben Produkte gezeigt?","Kannst du den freien Weg zur Werkstatt einzeichnen und sein Maß aus M3 dazuschreiben?","Kannst du „sehr gut“ an alle Möbel schreiben?","Warum ist eure Zeichnung nicht so groß wie die aus Leer?"],"answer":[3],"why":"Eine konkrete Rückfrage nennt, was ergänzt werden soll und woran es sich prüfen lässt.","hint":"Woran würde Jan den freien Zugang erkennen?","steps":"Beschreibe eine sichtbare Verbesserung und die passende Materialstelle.","example":"„Markiere den Gang und gib seine Breite an“ hilft beim Überarbeiten einer Skizze.","id":68,"coreId":19,"reserveNo":1,"type":"multi","l":2,"c":2,"caseLabel":"LS 6.1 · Die Nachfrage an zwei Standorten vergleichen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M2","M3","M5"]},{"title":"Kollegiale Rückmeldung zur Warengruppe","scene":"Übungsvariante: Eine Gruppe schlägt für Leer „Zubehör für Familien prominent zeigen“ vor. Sie nennt weder eine Fundstelle noch wie Familien die Ware finden.","ask":"Welche Rückmeldungen helfen bei der nächsten Fassung?","options":["Ordnet die Gruppe nach der Lieblingsfarbe einer Person.","Ergänzt die acht Anfragen zu Familienausflügen aus M2 als Nachfragebeleg.","Gebt die Präsentation frei, weil „prominent“ eindeutig genug ist.","Schreibt dazu, wie Familien die Warengruppe ohne feste Beratung finden.","Nehmt die Auricher Werkstattmaße als Beleg für die Nachfrage in Leer.","Beschreibt ein konkretes Erkennungsmerkmal, etwa einen gut sichtbaren Gruppenhinweis."],"answer":[1,3,5],"why":"Der Nachfragebeleg erklärt die Auswahl. Ein beschriebener Suchweg macht die Präsentation prüfbar.","hint":"Gebt Rückmeldung zu Begründung und Umsetzung.","steps":"Nenne zuerst einen passenden Ort im Material. Formuliere dann, was die andere Gruppe in der Praxis sichtbar machen kann.","example":"Ein konkretes Schildthema lässt sich im Modell prüfen. „Prominent“ allein sagt wenig.","id":69,"coreId":19,"reserveNo":2,"type":"multi","l":2,"c":2,"caseLabel":"LS 6.1 · Die Nachfrage an zwei Standorten vergleichen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M2","M3","M5"]},{"title":"Einen Unterschied kurz zeigen","scene":"Im Pitch habt ihr wenig Zeit. Jan möchte wissen, warum der Aufbau in Aurich und Leer verschieden sein kann.","ask":"Welcher Satz passt zu seinem Anliegen?","options":["Wir haben zwei Skizzen auf dem Tablet erstellt.","Wir haben bei jedem Laden 20 Anfragen vorliegen.","Bei uns hat die Abstimmung zehn Minuten gedauert.","Bei Block wird Zubehör persönlich gezeigt, während in Leer die Selbstbedienung verständliche Hinweise benötigt.","Unser Team hat zwei Farbvarianten ausprobiert.","Beide Läden verkaufen Fahrradzubehör, deshalb reicht derselbe Aufbau."],"answer":[3],"why":"Der Satz nennt den Unterschied und die Folge für die Präsentation in Leer. Damit trägt er zur Entscheidung bei.","hint":"Jan braucht eine Auswirkung, nicht euren gesamten Arbeitsbericht.","steps":"Verbinde eine Fallangabe mit einer konkreten Folge für den Aufbau.","example":"„Viele bringen ihr Rad mit, deshalb planen wir Beratungsplatz am Fahrrad ein“ ist eine kurze Begründung.","id":70,"coreId":20,"reserveNo":1,"type":"multi","l":2,"c":2,"caseLabel":"LS 6.1 · Die Nachfrage an zwei Standorten vergleichen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["Handlungssituation","M1","M2","M5"]},{"title":"Ein passendes Pitch-Paar wählen","scene":"Übungsvariante: Im Kurzpitch sollt ihr zeigen, weshalb die Wege den Aufbau an beiden Standorten beeinflussen. Ihr könnt je Laden einen Satz sagen.","ask":"Welche zwei Sätze passen als Belege und Folgen zusammen?","options":["Leer hat Familien, also dürfen wir die Gondel in den Hauptgang stellen.","Bei Block bleibt der 1,20 m breite Hauptdurchgang zur Werkstatt frei.","Block zählt 20 Fragen, also ist der Gang so breit wie in Leer.","Wir haben bei beiden Läden ein Schild, also sind die Kundenwege gleich.","In Leer bleibt der Hauptgang an der langen Seite offen; beide Warenseiten der Gondeln sollen erreichbar sein.","Unser Team hat unser wichtigstes Material mit einer Farbe markiert."],"answer":[1,4],"why":"Die zwei Sätze machen die konkrete Laufwegsituation beider Läden sichtbar. So erkennt Jan, warum derselbe Möbelplan nicht ohne Prüfung übernommen werden kann.","hint":"Suche pro Laden einen Lage- oder Maßbeleg.","steps":"Vergleiche zwei Aussagen zum gleichen Kriterium und fasse ihre Folgen zusammen.","example":"Für einen Pitch zur Fläche passen je Standort Angaben zum Kundenzugang besser als zwei bloße Kundenzahlen.","id":71,"coreId":20,"reserveNo":2,"type":"multi","l":2,"c":2,"caseLabel":"LS 6.1 · Die Nachfrage an zwei Standorten vergleichen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["Handlungssituation","M1","M2","M5"]},{"title":"Eine Fundstelle eingrenzen","scene":"In eurer Matrix lautet die Zeile: „In Leer beide Seiten der Gondeln erreichbar halten.“ Als Beleg steht nur „Material“.","ask":"Welche Einträge machen die Zeile nachprüfbar?","options":["M1 nennt das Werkstattgespräch in Aurich.","M3 zeigt zwei beidseitig bestückte Gondeln für Leer.","Den Beleg streichen, wenn die Anforderung schon eindeutig klingt.","M4 sagt, dass Kundinnen an beide langen Seiten gelangen müssen.","Die Größe der gesamten Bike Arena als einzigen Beleg nennen.","Eine allgemeine Shopbewertung hinzufügen."],"answer":[1,3],"why":"M3 beschreibt die Regale und M4 die vorgesehene Erreichbarkeit. Beide Stellen beziehen sich direkt auf die Empfehlung.","hint":"Such nach dem Wort „beide“.","steps":"Gib Fundstelle und passende Einzelangabe an.","example":"Eine Quellenangabe erklärt mehr, wenn daneben steht, welche Aussage du daraus entnommen hast.","id":72,"coreId":21,"reserveNo":1,"type":"multi","l":2,"c":4,"caseLabel":"LS 6.1 · Die Nachfrage an zwei Standorten vergleichen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M3","M5"]},{"title":"Eine Zeile prüfen und verbessern","scene":"Übungsvariante: Im digitalen Ergebnis steht „Licht am Fahrrad vorführen – M2“. Du prüfst die Empfehlung für Block.","ask":"Welche Überarbeitung macht den Eintrag belastbar?","options":["M2 unverändert lassen, weil dort auch Fahrradzubehör vorkommt.","M1 als Beleg für die Nachfrage nach einer Vorführung am Lenker angeben.","M3 als Beleg für genau neun verkaufte Lampen angeben.","Nur das Wort „Vorführung“ fett setzen.","Die Platzvorgabe aus M3 ergänzen, damit das Fahrrad beim Zeigen den Weg nicht verstellt.","Die Nachricht aus Leer als einzige Quelle für persönliche Beratung in Aurich verwenden."],"answer":[1,4],"why":"M1 stützt den Kundenwunsch nach einer Vorführung. M3 ergänzt die räumliche Bedingung für den Aufbau.","hint":"Frage nach einem Beleg für das Warum und einem für das Wie.","steps":"Prüfe den richtigen Standort und ergänze die konkrete Stelle zu Nachfrage und Durchführung.","example":"Ein Kundenwunsch kann die Vorführung begründen; der Flächenplan zeigt, wie sie möglich ist.","id":73,"coreId":21,"reserveNo":2,"type":"multi","l":2,"c":4,"caseLabel":"LS 6.1 · Die Nachfrage an zwei Standorten vergleichen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M3","M5"]},{"title":"Den Zugang einzeichnen","scene":"Im Sprechtext zu Block bleibt der Werkstattzugang frei. In M3 endet der links verlaufende Hauptdurchgang oben am Werkstattzugang. In der Skizze ist der Zugang oben, aber rechts eingezeichnet.","ask":"Was änderst du?","options":["Den Zugang an das obere Ende des linken Durchgangs setzen.","Den Durchgang rechts einzeichnen, ohne M3 abzugleichen.","Den Zugang in der Skizze entfernen und den Sprechtext allein verwenden.","Das Maß aus Leer übernehmen.","Die Breite der Aktionsfläche statt des Hauptgangs beschriften.","Den Zugang beim Tresen lassen, damit die Wege kürzer aussehen."],"answer":[0],"why":"M3 gibt die genaue Lage des freien Zugangs vor. Die Skizze muss den linken Durchgang und sein oberes Ende richtig wiedergeben.","hint":"Wo führt der in M3 eingezeichnete Weg hin?","steps":"Folge dem Durchgang in der Skizzenhilfe und setze den Zugang an sein Ende.","example":"Auch eine korrekte Raumfläche hilft wenig, wenn ein wichtiger Zugang auf der falschen Seite liegt.","id":74,"coreId":22,"reserveNo":1,"type":"multi","l":2,"c":4,"caseLabel":"LS 6.1 · Die Nachfrage an zwei Standorten vergleichen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M3","M4"]},{"title":"Eine zweite Skizze nachprüfen","scene":"Übungsvariante: Dein digitaler Plan für Leer zeigt nur eine Gondel. Die Nachricht nennt zwei Regale, die von beiden Seiten genutzt werden. In M3 stehen zwei Gondeln mit je 1,60 m × 0,60 m.","ask":"Welche Schritte beheben die Abweichung?","options":["Plan und Texte abgleichen und die zweite Gondel im vorgesehenen Maß ergänzen.","Den Sprechtext korrigieren, damit nur noch ein Regal vorkommt.","Die zweite Gondel zeichnen, aber ihre Tiefe aus Aurich übernehmen.","Nach dem Ergänzen Wege und beide Seiten der Gondeln erneut auf Zugänglichkeit prüfen.","Die zweite Gondel ohne Platzprüfung in den Hauptgang setzen.","Die Stellung der Möbel nur nach Bildsymmetrie wählen."],"answer":[0,3],"why":"Zwei Quellen bestätigen Anzahl und Nutzung. Ergänzt man ein Möbel, kann sich die Erreichbarkeit ändern und muss neu geprüft werden.","hint":"Was ändern Anzahl und Maße für die Wege?","steps":"Ergänze zuerst die fehlende Gondel maßstäblich und verfolge danach die möglichen Wege zu jeder Warenseite.","example":"Ein zweites Regal beeinflusst den verfügbaren Platz, auch wenn der erste Entwurf allein gut funktioniert.","id":75,"coreId":22,"reserveNo":2,"type":"multi","l":2,"c":4,"caseLabel":"LS 6.1 · Die Nachfrage an zwei Standorten vergleichen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M3","M4"]},{"title":"Gemeinsames Motiv, eigener Aufbau","scene":"Beide Läden sollen erkennbar dieselbe Aktion zeigen. Block hat persönliche Beratung am Rad, Leer vor allem Selbstbedienung auf der Aktionsfläche.","ask":"Welche Empfehlungen kannst du begründen?","options":["Dasselbe Personalmodell an beiden Standorten voraussetzen.","Ein gemeinsames Erscheinungsbild planen.","Alle räumlichen Vorgaben zugunsten eines einheitlichen Aufbaus streichen.","Aufbau und Informationen an der Auswahl im jeweiligen Laden ausrichten.","Weil beide Läden Fahrräder verkaufen, reicht die gleiche Warengruppe als Flächenplan.","Das Schildermotiv automatisch als Lösung für alle Platzprobleme ansehen."],"answer":[1,3],"why":"Eine einheitliche Aktion ist möglich. Die praktische Anordnung muss weiterhin zur Beratung, Selbstbedienung und örtlichen Fläche passen.","hint":"Welcher Teil kann wirklich gemeinsam bleiben?","steps":"Prüfe Gestaltung und Nutzung getrennt. Verknüpfe die Nutzung mit dem jeweiligen Laden.","example":"Ein gemeinsames Logo erlaubt ein Hinweisschild am Regal in einem Laden und eine Thekeninfo im anderen.","id":76,"coreId":23,"reserveNo":1,"type":"multi","l":2,"c":0,"caseLabel":"LS 6.1 · Die Nachfrage an zwei Standorten vergleichen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["Handlungssituation","M1","M2","M3","M5"]},{"title":"Eine Alternative freigeben","scene":"Übungsvariante: Global Bike hat für beide Läden dasselbe Banner. In Aurich bleibt mit dem vorgeschlagenen Rollregal der Werkstattzugang nicht frei. In Leer verdeckt der geplante Schildhalter die zweite Warenseite der Gondel.","ask":"Welche Empfehlung ist umsetzbar?","options":["Banner und sämtliche Möbel unverändert übernehmen, weil die Kampagne gemeinsam ist.","Nur den Zugang in Leer prüfen; die kleinere Filiale muss sich anpassen.","Das gemeinsame Banner beibehalten und die problematischen Möbelpositionen je Laden ändern.","Beide Läden auf feste persönliche Beratung umstellen.","Beide Änderungen beim Probeaufbau getrennt auf freie Wege und Erreichbarkeit prüfen.","Alle Möbelpläne anhand des größeren Ladens freigeben."],"answer":[2,4],"why":"Das gemeinsame Banner ist möglich. Die Pläne müssen jeweils den freien Zugang in Aurich und die beidseitige Erreichbarkeit in Leer sichern.","hint":"Welcher Mangel betrifft welchen Standort?","steps":"Nenne pro Laden eine betroffene Vorgabe und prüfe sie nach der jeweiligen Anpassung erneut.","example":"Ein gemeinsames Motiv kann bleiben, auch wenn sich die Stellpläne unterscheiden.","id":77,"coreId":23,"reserveNo":2,"type":"multi","l":2,"c":0,"caseLabel":"LS 6.1 · Die Nachfrage an zwei Standorten vergleichen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["Handlungssituation","M1","M2","M3","M5"]}];
